package io.github.y5c.gebridge;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarbitID;

/**
 * Achievement diary completion, read from the game's completion varbits. Pure: the varbit lookup is passed in.
 *
 * <p>Each tier is complete when its varbit reaches the value the game itself checks for: 1, except Karamja's easy,
 * medium and hard tiers, which the game marks complete at 2.
 */
final class AccountData
{
	static final String[] TIERS = {"easy", "medium", "hard", "elite"};

	/** key, display name, then for each tier: varbit, value meaning complete. */
	static final Object[][] DIARIES = {
		{"ardougne", "Ardougne", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 1, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, 1, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE, 1},
		{"desert", "Desert", VarbitID.DESERT_DIARY_EASY_COMPLETE, 1, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, 1, VarbitID.DESERT_DIARY_ELITE_COMPLETE, 1},
		{"falador", "Falador", VarbitID.FALADOR_DIARY_EASY_COMPLETE, 1, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, 1, VarbitID.FALADOR_DIARY_ELITE_COMPLETE, 1},
		{"fremennik", "Fremennik", VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, 1, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, 1, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE, 1},
		{"kandarin", "Kandarin", VarbitID.KANDARIN_DIARY_EASY_COMPLETE, 1, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, 1, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE, 1},
		{"karamja", "Karamja", VarbitID.ATJUN_EASY_DONE, 2, VarbitID.ATJUN_MED_DONE, 2,
			VarbitID.ATJUN_HARD_DONE, 2, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, 1},
		{"kourend_kebos", "Kourend & Kebos", VarbitID.KOUREND_DIARY_EASY_COMPLETE, 1, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, 1, VarbitID.KOUREND_DIARY_ELITE_COMPLETE, 1},
		{"lumbridge_draynor", "Lumbridge & Draynor", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, 1, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, 1, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE, 1},
		{"morytania", "Morytania", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, 1, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, 1, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE, 1},
		{"varrock", "Varrock", VarbitID.VARROCK_DIARY_EASY_COMPLETE, 1, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, 1, VarbitID.VARROCK_DIARY_ELITE_COMPLETE, 1},
		{"western_provinces", "Western Provinces", VarbitID.WESTERN_DIARY_EASY_COMPLETE, 1, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, 1, VarbitID.WESTERN_DIARY_ELITE_COMPLETE, 1},
		{"wilderness", "Wilderness", VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, 1, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, 1, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE, 1},
	};

	private AccountData()
	{
	}

	/** The diaries block of account.json, in the field layout the Local Data Exporter used. */
	static Map<String, Object> diaries(IntUnaryOperator varbit)
	{
		final Map<String, Object> regions = new LinkedHashMap<>();
		int done = 0;
		int total = 0;
		for (Object[] d : DIARIES)
		{
			final Map<String, Object> r = new LinkedHashMap<>();
			r.put("name", d[1]);
			int rd = 0;
			for (int t = 0; t < TIERS.length; t++)
			{
				final int value = varbit.applyAsInt((Integer) d[2 + 2 * t]);
				final boolean complete = value >= (Integer) d[3 + 2 * t];
				final Map<String, Object> tier = new LinkedHashMap<>();
				tier.put("complete", complete);
				tier.put("value", value);
				r.put(TIERS[t], tier);
				rd += complete ? 1 : 0;
			}
			r.put("completedTierCount", rd);
			r.put("totalTierCount", TIERS.length);
			r.put("allComplete", rd == TIERS.length);
			regions.put((String) d[0], r);
			done += rd;
			total += TIERS.length;
		}
		final Map<String, Object> out = new LinkedHashMap<>();
		out.put("source", "diary completion varbits");
		out.put("completedTierCount", done);
		out.put("totalTierCount", total);
		out.put("completionPercent", total == 0 ? 0 : Math.round(1000.0 * done / total) / 10.0);
		out.put("regions", regions);
		return out;
	}
}

package io.github.y5c.gebridge;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * advice.json: what the player's own tool advises for the Grand Exchange, written by that tool into the plugin's data
 * folder. The plugin only displays it and compares it with what is on screen; it never acts on it.
 *
 * <pre>
 * {"schema": 1, "generatedAt": epoch ms,
 *  "slots":  [{"slot", "itemId", "item", "side", "price", "total", "action", "text"}],   advice for the order now in a slot
 *             (optional: listAt, trimTo, holdUntil, holdTrimTo, replaceTo, stallCancel — the reminders' prices)
 *  "orders": [{"itemId", "item", "side", "price", "qty", "why", "slot"}],              orders the player should place
 *  "deadlines": {"askGraceHours", "bidStallHours", "bidDeadHours"}}                    the tool's clocks, for reminders (0.7.0)
 * </pre>
 *
 * A slot entry applies only while that same order (item, side, price, quantity) is still in the slot. An order counts
 * as placed once a slot holds it. {@code qty} may be absent, in which case the quantity is not checked. {@code slot}
 * (optional) names the slot whose advice the order carries out; the order is not listed while that advice shows.
 *
 * <p>Pure: no client types. Fields are filled by Gson.
 */
final class Advice
{
	static final int SCHEMA = 1;

	static final class Slot
	{
		int slot = -1;
		int itemId;
		String item;
		String side;
		long price;
		int total;
		String action;
		String text;
		// a bid: the price to list at once it completes (0.6.3)
		Long listAt;
		// an ask: the trim its grace leads to; a held price dip: when the hold ends and the price it then trims to (0.7.0)
		Long trimTo;
		Long holdUntil;
		Long holdTrimTo;
		// a kept bid: what a check-in would do if it stalls — re-place to this price, or cancel (0.7.3)
		Long replaceTo;
		Boolean stallCancel;
	}

	/** The tool's own clocks, in hours, which the reminders run against each order's times (0.7.0). */
	static final class Deadlines
	{
		Double askGraceHours;
		Double bidStallHours;
		Double bidDeadHours;
	}

	static final class Order
	{
		int itemId;
		String item;
		String side;
		long price;
		Integer qty;
		String why;
		// the slot whose advice this order carries out (a trim, a re-place, a listing), when there is one
		Integer slot;
		// a bid: the price to list at once it completes (0.6.3)
		Long listLater;
		// the sale of a cancelled bid's units: what the bid had actually bought when it was cancelled (0.7.2). Transient:
		// seen in the client, not read from the file
		transient Integer bought;

		/** The quantity to place: the units a cancelled bid really bought, when known, else the advised quantity. */
		Integer qty()
		{
			return bought != null ? bought : qty;
		}
	}

	/** What the offer screen shows against the advice: {@code level} is ok, warn or none (no advice for the item). */
	static final class Check
	{
		final String level;
		final List<String> lines;

		Check(String level, List<String> lines)
		{
			this.level = level;
			this.lines = lines;
		}
	}

	int schema;
	long generatedAt;
	List<Slot> slots;
	List<Order> orders;
	Deadlines deadlines;
	// orders seen placed since this advice loaded, kept even once their slot is empty again: a sell to the standing
	// buyers fills and is collected in seconds, and its slot never shows it to a later check (0.6.5). Transient: not
	// read from the file; a new advice file starts empty.
	private transient Set<Order> placed;

	boolean usable()
	{
		return schema == SCHEMA && generatedAt > 0;
	}

	List<Slot> slots()
	{
		return slots == null ? Collections.emptyList() : slots;
	}

	List<Order> orders()
	{
		return orders == null ? Collections.emptyList() : orders;
	}

	/** The advice for the order in {@code slot}, or null when there is none or the slot now holds a different order. */
	Slot forSlot(int slot, OfferTracker.Offer o)
	{
		if (o == null || o.isEmpty())
		{
			return null;
		}
		for (Slot s : slots())
		{
			if (s.slot == slot && sameItem(s.itemId, s.item, o) && o.side().equals(s.side) && s.price == o.price && s.total == o.total)
			{
				return s;
			}
		}
		return null;
	}

	/** The advised order this offer carries out, or null (an order the advice never named). */
	Order orderFor(OfferTracker.Offer o)
	{
		for (Order a : orders())
		{
			if (matches(a, o))
			{
				return a;
			}
		}
		return null;
	}

	/** The slot holding this advised order, or -1. */
	static int placedIn(Order a, OfferTracker.Offer[] now)
	{
		for (int i = 0; i < now.length; i++)
		{
			final OfferTracker.Offer o = now[i];
			if (o != null && !o.isEmpty() && matches(a, o))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * An order has just been placed: remember the advised order it carries out, so the order stays off the list after
	 * it completes and is collected. One advised order per placement, the first not already seen.
	 */
	void markPlaced(OfferTracker.Offer o)
	{
		if (o == null || o.isEmpty())
		{
			return;
		}
		if (placed == null)
		{
			placed = new HashSet<>();
		}
		for (Order a : orders())
		{
			if (!placed.contains(a) && matches(a, o))
			{
				placed.add(a);
				return;
			}
		}
	}

	private boolean seenPlaced(Order a)
	{
		return placed != null && placed.contains(a);
	}

	/**
	 * An advised bid has just been cancelled with {@code o.done} units bought: the sale of its units takes that count, not
	 * the check-in's (0.7.2; 2026-10-27: 25 amulets filled between the check-in and the cancel, and the offer screen
	 * warned that 272 was not the advised 247). The sale is the order that carries out this slot's advice on the other side.
	 */
	void boughtOut(int slot, OfferTracker.Offer o)
	{
		if (o == null || o.isEmpty() || !"buy".equals(o.side()) || forSlot(slot, o) == null)
		{
			return;
		}
		for (Order a : orders())
		{
			if (a.slot != null && a.slot == slot && "sell".equals(a.side) && sameItem(a.itemId, a.item, o))
			{
				a.bought = o.done;
			}
		}
	}

	/** Advised orders no slot holds yet and not seen placed. */
	List<Order> open(OfferTracker.Offer[] now)
	{
		final List<Order> out = new ArrayList<>();
		for (Order a : orders())
		{
			if (!seenPlaced(a) && placedIn(a, now) < 0)
			{
				out.add(a);
			}
		}
		return out;
	}

	/**
	 * The orders to list under "place": the open ones, less those that carry out the advice of a slot still showing
	 * it. A trim reads "trim to 49,726" on its slot; it is listed as an order only once that slot has changed.
	 */
	List<Order> toPlace(OfferTracker.Offer[] now)
	{
		final List<Order> out = new ArrayList<>();
		for (Order a : open(now))
		{
			if (a.slot != null && a.slot >= 0 && a.slot < now.length && forSlot(a.slot, now[a.slot]) != null)
			{
				continue;
			}
			if (a.qty() != null && a.qty() == 0)
			{
				continue;      // a cancelled bid that had bought nothing: nothing to sell
			}
			out.add(a);
		}
		return out;
	}

	/**
	 * The offer screen, before Confirm: the item, side and quantity the player has set. The price typed is not compared
	 * here (the client keeps it in a variable RuneLite has not named); it is checked once the order is in its slot.
	 */
	Check check(int itemId, String side, int qty, OfferTracker.Offer[] now)
	{
		final List<String> lines = new ArrayList<>();
		final List<Order> same = new ArrayList<>();
		Order other = null;
		for (Order a : orders())
		{
			if (a.itemId != itemId)
			{
				continue;
			}
			if (side.equals(a.side))
			{
				same.add(a);
			}
			else
			{
				other = a;
			}
		}
		if (same.isEmpty())
		{
			// a completed, collected bid: its advice to sell is the buy order's list price (0.6.6; nihil dust 2026-10-13
			// read "Advice is to buy this item, not sell")
			if (other != null && "sell".equals(side) && "buy".equals(other.side) && other.listLater != null)
			{
				// the item is already chosen on the offer screen: quantity and price only, on one line
				lines.add("sell " + (other.qty == null ? "" : fmt(other.qty) + " ") + "@ " + fmt(other.listLater) + " (cost " + fmt(other.price) + ")");
				if (other.qty != null && qty > other.qty)
				{
					lines.add("Quantity " + fmt(qty) + " is more than the " + fmt(other.qty) + " advised");
					return new Check("warn", lines);
				}
				return new Check("ok", lines);
			}
			if (other != null)
			{
				lines.add("Advice is to " + other.side + " this item, not " + side);
				lines.add(describe(other));
				return new Check("warn", lines);
			}
			lines.add("No advice for this item");
			return new Check("none", lines);
		}
		boolean qtyOk = false;
		for (Order a : same)
		{
			if (a.qty() == null || a.qty() == qty)
			{
				qtyOk = true;
			}
		}
		for (Order a : same)
		{
			final int in = placedIn(a, now);
			lines.add(describe(a) + (in >= 0 ? " (already in slot " + in + ")" : ""));
		}
		// the units of an advised bid are another advised sale of the item, at the bid's list price (0.6.7)
		if ("sell".equals(side) && other != null)
		{
			for (Order b : orders())
			{
				if (b.itemId == itemId && "buy".equals(b.side) && b.listLater != null)
				{
					lines.add("or sell " + (b.qty == null ? "" : fmt(b.qty) + " ") + "@ " + fmt(b.listLater) + " (cost " + fmt(b.price) + ")");
					if (b.qty == null || qty <= b.qty)
					{
						qtyOk = true;
					}
				}
			}
		}
		boolean warn = false;
		if (!qtyOk)
		{
			lines.add("Quantity " + fmt(qty) + " is not the advised " + fmt(same.get(0).qty()));
			warn = true;
		}
		for (Order a : same)
		{
			if (placedIn(a, now) >= 0 && same.size() == 1)
			{
				lines.add("This order is already placed: a second one would double it");
				warn = true;
			}
		}
		return new Check(warn ? "warn" : "ok", lines);
	}

	/**
	 * A new order the player has just placed, against the advice for its item and side. Null when it matches an advised
	 * order or there is no advice for it; otherwise the warning to show.
	 */
	String placedMismatch(OfferTracker.Offer o)
	{
		if (listsABid(o))
		{
			return null;
		}
		Order near = null;
		for (Order a : orders())
		{
			if (!sameItem(a.itemId, a.item, o) || !o.side().equals(a.side))
			{
				continue;
			}
			if (matches(a, o))
			{
				return null;
			}
			near = a;
		}
		if (near == null)
		{
			return null;
		}
		final List<String> diff = new ArrayList<>();
		if (near.price != o.price)
		{
			diff.add("price " + fmt(o.price) + " (advised " + fmt(near.price) + ")");
		}
		if (near.qty() != null && near.qty() != o.total)
		{
			diff.add("qty " + fmt(o.total) + " (advised " + fmt(near.qty()) + ")");
		}
		return AdviceView.shorten(o.item, AdviceView.SLOT_NAME) + ": " + String.join(", ", diff);
	}

	/**
	 * The price to list a completed buy at: from the advice for its slot, else from the advised order it is (a pick placed
	 * since the check-in). Null when the advice gives none.
	 */
	Long listAt(int slot, OfferTracker.Offer o)
	{
		if (o == null || o.isEmpty() || !"buy".equals(o.side()))
		{
			return null;
		}
		final Slot s = forSlot(slot, o);
		if (s != null && s.listAt != null)
		{
			return s.listAt;
		}
		for (Order a : orders())
		{
			if (a.listLater != null && matches(a, o))
			{
				return a.listLater;
			}
		}
		return null;
	}

	/**
	 * A sell at the list price an advised bid carries (listLater), for no more than the bid's quantity: the advice for the
	 * units that bid bought, even while another ask of the same item is advised (0.6.7; bagged plant 2026-10-15: the
	 * sale at the bid's 2,150 was flagged against another slot's 2,182 and re-listed at the buy price).
	 */
	boolean listsABid(OfferTracker.Offer o)
	{
		if (o == null || o.isEmpty() || !"sell".equals(o.side()))
		{
			return false;
		}
		for (Order a : orders())
		{
			if ("buy".equals(a.side) && a.listLater != null && sameItem(a.itemId, a.item, o) && a.listLater == o.price
				&& (a.qty == null || o.total <= a.qty))
			{
				return true;
			}
		}
		return false;
	}

	static boolean matches(Order a, OfferTracker.Offer o)
	{
		return sameItem(a.itemId, a.item, o) && o.side().equals(a.side) && a.price == o.price && (a.qty() == null || a.qty() == o.total);
	}

	private static boolean sameItem(int itemId, String item, OfferTracker.Offer o)
	{
		if (itemId > 0)
		{
			return itemId == o.itemId;
		}
		return item != null && item.equalsIgnoreCase(o.item);
	}

	static String describe(Order a)
	{
		return a.side + " " + (a.qty() == null ? "" : fmt(a.qty()) + " ") + a.item + " at " + fmt(a.price);
	}

	static String fmt(Number n)
	{
		return n == null ? "?" : String.format(Locale.US, "%,d", n.longValue());
	}

	/** "25m", "3h", "2d": the advice's age. */
	static String age(long ms)
	{
		final long m = Math.max(0, ms / 60_000);
		if (m < 60)
		{
			return m + "m";
		}
		if (m < 48 * 60)
		{
			return (m / 60) + "h";
		}
		return (m / 1440) + "d";
	}
}

package io.github.y5c.gebridge;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.Text;

/** A panel listing the advice while the Grand Exchange is open. Display only. */
final class AdviceOverlay extends OverlayPanel
{
	private static final int WIDTH = 240;
	/** The panel widens to fit its longest line up to this (0.7.4); a longer line still wraps. */
	static final int MAX_WIDTH = 480;
	/** Space kept between a line's left and right text. */
	private static final int GAP = 8;

	private final GeBridgePlugin plugin;

	@Inject
	AdviceOverlay(GeBridgePlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final AdviceView v = plugin.adviceView();
		if (v.header == null)
		{
			return null;
		}
		fill(panelComponent, v, g.getFontMetrics());
		return super.render(g);
	}

	/** The panel's contents; also used to render the panel outside the game. */
	static void fill(PanelComponent panel, AdviceView v, FontMetrics fm)
	{
		panel.setPreferredSize(new Dimension(width(v, fm), 0));
		panel.getChildren().add(TitleComponent.builder().text(v.header).color(v.headerColor).build());
		for (AdviceView.Line l : v.lines)
		{
			panel.getChildren().add(LineComponent.builder()
				.left(l.left).leftColor(l.color)
				.right(l.right == null ? "" : l.right).rightColor(l.color)
				.build());
		}
	}

	/** Wide enough for every line on one line (left, a gap, right), never under the old 240 nor over {@link #MAX_WIDTH}. */
	static int width(AdviceView v, FontMetrics fm)
	{
		int need = fm.stringWidth(Text.removeTags(v.header));
		for (AdviceView.Line l : v.lines)
		{
			final int right = l.right == null || l.right.isEmpty() ? 0 : GAP + fm.stringWidth(Text.removeTags(l.right));
			need = Math.max(need, fm.stringWidth(Text.removeTags(l.left)) + right);
		}
		return Math.max(WIDTH, Math.min(MAX_WIDTH, need + 2 * ComponentConstants.STANDARD_BORDER));
	}
}

package io.github.y5c.gebridge;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** What the two overlays draw, rebuilt on the client thread each tick while the Grand Exchange is open. Immutable. */
final class AdviceView
{
	static final Color OK = new Color(0x7fd27f);
	static final Color WARN = new Color(0xff5c5c);
	static final Color ACT = new Color(0xffd23f);
	static final Color DIM = new Color(0xa0a0a0);
	static final Color TEXT = Color.WHITE;

	static final AdviceView NONE = new AdviceView(null, DIM, Collections.emptyList(), Collections.emptyMap());

	static final class Line
	{
		final String left;
		final String right;
		final Color color;

		Line(String left, String right, Color color)
		{
			this.left = left;
			this.right = right;
			this.color = color;
		}
	}

	final String header;
	final Color headerColor;
	final List<Line> lines;
	// slot -> outline colour
	final Map<Integer, Color> slots;

	AdviceView(String header, Color headerColor, List<Line> lines, Map<Integer, Color> slots)
	{
		this.header = header;
		this.headerColor = headerColor;
		this.lines = lines;
		this.slots = slots;
	}

	// the compact layout (user's pick, 2026-10-11): actions in a word or two. Names were cut to 20/18 to fit a fixed
	// 240 px panel; the panel now widens to its longest line (0.7.4, user 2026-10-28), so only very long names are cut
	static final int SLOT_NAME = 32;
	static final int ORDER_NAME = 32;

	/**
	 * A name cut to at most {@code n} characters, keeping its last three: "Divine battlemag…(4)". The ending is what tells
	 * an item's doses, charges or tiers apart, so it is never the part dropped.
	 */
	static String shorten(String s, int n)
	{
		if (s == null || s.length() <= n || n < 6)
		{
			return s;
		}
		return s.substring(0, n - 4).trim() + "…" + s.substring(s.length() - 3);
	}

	/** The advice's action in a word or two: "trim to 1,280" -> "trim 1,280". */
	static String compact(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replace("collect, list at ", "list ").replace("trim to ", "trim ").replace("re-place at ", "bid ")
			.replace("sell at ", "sell ").replace("cancel, list ", "cancel; list ").replace(" at ", " @ ");
	}

	private static final java.util.regex.Pattern LIST_UNITS = java.util.regex.Pattern.compile("list [0-9][0-9,]*");

	/**
	 * A bid advised to be cancelled or re-placed, with the units it has bought listed: the count as the slot has it now,
	 * not as it was at the check-in — a bid keeps filling until it is cancelled (0.7.2).
	 */
	static String liveUnits(Advice.Slot a, OfferTracker.Offer o)
	{
		if (a.text == null || o == null || !"buy".equals(o.side()) || o.done <= 0)
		{
			return a.text;
		}
		return LIST_UNITS.matcher(a.text).replaceFirst("list " + Advice.fmt(o.done));
	}

	/**
	 * What to draw. Pure, so the panel can be rendered and checked outside the game.
	 *
	 * @param offers     the eight slots as the plugin last saw them
	 * @param mismatches slot -> how the order just placed there differs from the advice
	 * @param check      the offer screen's check, or null when no new offer is being set up
	 * @param maxAgeMs   older advice is shown as out of date and not used
	 */
	static AdviceView build(Advice advice, OfferTracker.Offer[] offers, Map<Integer, String> mismatches, Advice.Check check,
		long now, long maxAgeMs, boolean highlight)
	{
		return build(advice, offers, mismatches, check, now, maxAgeMs, highlight, Collections.emptyMap());
	}

	/**
	 * As above, with the reminders' clocks (0.7.1): a kept order with a deadline gets its own line — the action and the time
	 * left ("trim 3,362 in 2h10m", dim), or, once it has passed, "now: trim 3,362" in the action colour with its slot
	 * outlined; so does an advised order placed after the check-in. Kept orders without a deadline are still only counted.
	 */
	static AdviceView build(Advice advice, OfferTracker.Offer[] offers, Map<Integer, String> mismatches, Advice.Check check,
		long now, long maxAgeMs, boolean highlight, Map<Integer, Reminders.Clock> clocks)
	{
		if (advice == null)
		{
			return NONE;
		}
		final long age = now - advice.generatedAt;
		final String header = "Advice (" + Advice.age(age) + " old)";
		final List<Line> lines = new ArrayList<>();
		final Map<Integer, Color> slots = new LinkedHashMap<>();
		if (age > maxAgeMs)
		{
			lines.add(new Line("Out of date: run your tool again", null, DIM));
			return new AdviceView(header, DIM, lines, slots);
		}
		if (check != null)
		{
			final Color color = "ok".equals(check.level) ? OK : "warn".equals(check.level) ? WARN : DIM;
			for (String l : check.lines)
			{
				lines.add(new Line(l, null, color));
			}
			return new AdviceView(header, TEXT, lines, slots);
		}
		for (Map.Entry<Integer, String> m : mismatches.entrySet())
		{
			lines.add(new Line(m.getKey() + " " + m.getValue(), null, WARN));
			slots.put(m.getKey(), WARN);
		}
		int keep = 0;
		for (int i = 0; i < OfferTracker.SLOTS; i++)
		{
			final OfferTracker.Offer o = offers[i];
			if (o != null && !o.personal && "BOUGHT".equals(o.state))
			{
				// a buy that finished since the check-in: say where to list it now, not at the next check-in (0.6.3)
				final Long at = advice.listAt(i, o);
				if (at != null)
				{
					lines.add(new Line(i + " " + shorten(o.item, SLOT_NAME), "list " + Advice.fmt(at), ACT));
					slots.putIfAbsent(i, ACT);
					continue;
				}
			}
			final Advice.Slot a = advice.forSlot(i, o);
			final Reminders.Clock c = clocks.get(i);
			if (c != null && (a == null || "keep".equals(a.action)) && o != null && !o.personal)
			{
				lines.add(new Line(i + " " + shorten(o.item, SLOT_NAME), c.due ? "now: " + c.action : c.action + " in " + Reminders.left(c.at - now),
					c.due ? ACT : DIM));
				if (c.due)
				{
					slots.putIfAbsent(i, ACT);
				}
				continue;
			}
			if (a == null || o.personal)
			{
				continue;
			}
			if ("keep".equals(a.action))
			{
				keep++;
				continue;
			}
			lines.add(new Line(i + " " + shorten(a.item, SLOT_NAME), compact(liveUnits(a, o)), ACT));
			slots.putIfAbsent(i, ACT);
		}
		for (Advice.Order o : advice.toPlace(offers))
		{
			lines.add(new Line(("buy".equals(o.side) ? "+ " : "- ") + shorten(o.item, ORDER_NAME),
				(o.qty() == null ? "" : Advice.fmt(o.qty()) + " ") + "@ " + Advice.fmt(o.price), TEXT));
		}
		if (keep > 0)
		{
			lines.add(new Line(keep + (keep == 1 ? " slot" : " slots") + ": keep", null, DIM));
		}
		if (lines.isEmpty())
		{
			lines.add(new Line("Nothing to do", null, DIM));
		}
		return new AdviceView(header, TEXT, lines, highlight ? slots : new LinkedHashMap<>());
	}
}

package io.github.y5c.gebridge;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * What the game said when the player last used an item's "Check" option (0.6.8): a charged weapon's charges, a
 * blowpipe's darts and scales, a gem bag's or herb sack's contents. The game sends the answer as chat messages, not as
 * item data, so the messages that arrive within a few ticks of the click are kept as text, keyed by the item. Reading
 * them is left to the reader of state.json, so a new message format needs no plugin release. Pure: ticks and times
 * are passed in, so it is testable without a client.
 */
final class Checks
{
	/** Messages answering a click arrive on the next tick or two; later ones are something else. */
	static final int WINDOW_TICKS = 3;
	static final int MAX_LINES = 20;
	static final int MAX_ITEMS = 50;

	/** item id → {name, lines, timestamp}, in the order last checked. */
	private final Map<String, JsonObject> items = new java.util.LinkedHashMap<>();
	private int pendingId = -1;
	private String pendingName;
	private int pendingTick;
	private List<String> lines;

	static boolean isCheck(String option)
	{
		return option != null && option.trim().toLowerCase(Locale.ROOT).startsWith("check");
	}

	/** The player clicked Check on an item: the next messages, until the window closes, belong to it. */
	void clicked(int itemId, String name, int tick)
	{
		pendingId = itemId;
		pendingName = name;
		pendingTick = tick;
		lines = null;
	}

	/**
	 * A game message. Returns true when it was kept (state.json then needs writing). The first message replaces what
	 * the item's last check said; the rest of the same answer is added to it.
	 */
	boolean message(String text, int tick, long now)
	{
		if (pendingId <= 0 || tick - pendingTick > WINDOW_TICKS || text == null || text.trim().isEmpty())
		{
			return false;
		}
		if (lines == null)
		{
			lines = new ArrayList<>();
		}
		if (lines.size() >= MAX_LINES)
		{
			return false;
		}
		lines.add(text.trim());
		final JsonObject v = new JsonObject();
		v.addProperty("id", pendingId);
		v.addProperty("name", pendingName);
		final JsonArray a = new JsonArray();
		lines.forEach(a::add);
		v.add("lines", a);
		v.addProperty("timestamp", now);
		final String key = Integer.toString(pendingId);
		items.remove(key);
		items.put(key, v);
		while (items.size() > MAX_ITEMS)
		{
			items.remove(items.keySet().iterator().next());
		}
		return true;
	}

	/** The previous state.json's "checks", so a restart keeps the last answers. */
	void restore(JsonElement prev)
	{
		items.clear();
		if (prev == null || !prev.isJsonObject())
		{
			return;
		}
		for (Map.Entry<String, JsonElement> e : prev.getAsJsonObject().entrySet())
		{
			if (e.getValue().isJsonObject())
			{
				items.put(e.getKey(), e.getValue().getAsJsonObject());
			}
		}
	}

	void clear()
	{
		items.clear();
		pendingId = -1;
		lines = null;
	}

	JsonObject toJson()
	{
		final JsonObject out = new JsonObject();
		items.forEach(out::add);
		return out;
	}
}

package io.github.y5c.gebridge;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Recognises decanting in an inventory change: potions of one kind leave and potions of the same kind but other dose
 * sizes arrive, with the total number of doses unchanged (Bob Barter's decanting, or combining potions by hand).
 * Pure: works on names and quantities.
 */
final class Decants
{
	private static final Pattern DOSE = Pattern.compile("^(.*)\\((\\d)\\)$");

	private Decants()
	{
	}

	/** One change in quantity of one item: positive arrived, negative left. */
	static final class Change
	{
		final int id;
		final String name;
		final int delta;

		Change(int id, String name, int delta)
		{
			this.id = id;
			this.name = name;
			this.delta = delta;
		}
	}

	/** The decants in one inventory change, one map per potion kind; empty when there are none. */
	static List<Map<String, Object>> find(List<Change> changes)
	{
		final Map<String, List<Change>> byKind = new TreeMap<>();
		for (Change c : changes)
		{
			final Matcher m = c.name == null ? null : DOSE.matcher(c.name);
			if (m != null && m.matches() && c.delta != 0)
			{
				byKind.computeIfAbsent(m.group(1), k -> new ArrayList<>()).add(c);
			}
		}
		final List<Map<String, Object>> out = new ArrayList<>();
		for (Map.Entry<String, List<Change>> k : byKind.entrySet())
		{
			int dosesOut = 0;
			int dosesIn = 0;
			final List<Map<String, Object>> from = new ArrayList<>();
			final List<Map<String, Object>> to = new ArrayList<>();
			for (Change c : k.getValue())
			{
				final int dose = doses(c.name);
				final Map<String, Object> m = new LinkedHashMap<>();
				m.put("id", c.id);
				m.put("name", c.name);
				m.put("quantity", Math.abs(c.delta));
				if (c.delta < 0)
				{
					dosesOut += dose * -c.delta;
					from.add(m);
				}
				else
				{
					dosesIn += dose * c.delta;
					to.add(m);
				}
			}
			if (!from.isEmpty() && !to.isEmpty() && dosesOut == dosesIn)
			{
				final Map<String, Object> d = new LinkedHashMap<>();
				d.put("potion", k.getKey());
				d.put("doses", dosesOut);
				d.put("from", from);
				d.put("to", to);
				out.add(d);
			}
		}
		return out;
	}

	static int doses(String name)
	{
		final Matcher m = DOSE.matcher(name == null ? "" : name);
		return m.matches() ? Integer.parseInt(m.group(2)) : 0;
	}
}

package io.github.y5c.gebridge;

import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/**
 * The append-only event log, kept to a bounded size.
 *
 * <p>When events.jsonl reaches the size limit it is renamed to events-&lt;UTC time&gt;.jsonl and a new one is started;
 * only the newest {@link #KEEP} archives are kept. A rename keeps the file's identity, so a reader that was part-way
 * through events.jsonl can find the same file under its archive name and finish it. Called on the io thread only.
 */
final class EventLog
{
	static final String LIVE = "events.jsonl";
	static final int KEEP = 6;
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss").withZone(ZoneOffset.UTC);

	private EventLog()
	{
	}

	static void append(Filepath dir, String line, long maxBytes, long now) throws IOException
	{
		final Filepath live = dir.joinSegment(LIVE);
		if (live.exists() && live.size() >= maxBytes)
		{
			live.moveTo(dir.joinSegment(archiveName(now)));
			final List<String> names;
			try (Stream<Filepath> files = dir.walk(1))
			{
				names = files.map(Filepath::getFileName).collect(Collectors.toList());
			}
			for (String old : toDelete(names, KEEP))
			{
				dir.joinSegment(old).deleteIfExists();
			}
		}
		live.write(line, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
	}

	static String archiveName(long ms)
	{
		return "events-" + STAMP.format(Instant.ofEpochMilli(ms)) + ".jsonl";
	}

	static boolean isArchive(String name)
	{
		return name != null && name.matches("events-\\d{8}T\\d{6}\\.jsonl");
	}

	/** The archives beyond the newest {@code keep}; the names sort by time. */
	static List<String> toDelete(List<String> names, int keep)
	{
		final List<String> archives = new ArrayList<>();
		for (String n : names)
		{
			if (isArchive(n))
			{
				archives.add(n);
			}
		}
		Collections.sort(archives);
		return archives.size() <= keep ? Collections.emptyList() : archives.subList(0, archives.size() - keep);
	}
}

