	@Provides
	GeBridgeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GeBridgeConfig.class);
	}

	@Override
	protected void startUp()
	{
		io = Executors.newSingleThreadExecutor(r -> new Thread(r, "ge-bridge-io"));
		healthSince = System.currentTimeMillis();
		overlayManager.add(adviceOverlay);
		overlayManager.add(slotOverlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				// enabled mid-session: every slot is a first sight, compared against the remembered state
				loggedIn = true;
				loginTick = client.getTickCount() - RECONCILE_AFTER_TICKS;
				reconciled = false;
				lastLogin = OfferTracker.iso(System.currentTimeMillis());
				whenReady(() -> emit(simple("start")));
			}
		});
	}

	@Override
	protected void shutDown()
	{
		// The final save is made on the client thread, which owns the state. shutdown() rather than shutdownNow():
		// it does not block either, but it lets the already-queued writes (that final save included) finish instead
		// of discarding them, so the slot memory on disk is never older than the session.
		final ExecutorService ex = io;
		overlayManager.remove(adviceOverlay);
		overlayManager.remove(slotOverlay);
		clientThread.invoke(() ->
		{
			if (tracker != null && accountDir != null)
			{
				emit(simple("stop"));
				writeState(System.currentTimeMillis());
			}
			ex.shutdown();
			reset();
		});
	}

	private void reset()
	{
		accountHash = -1;
		accountDir = null;
		tracker = null;
		pending.clear();
		loggedIn = false;
		loginTick = -1;
		reconciled = false;
		dirty = false;
		rsn = null;
		exiting = false;
		skillsCache = inventoryCache = equipmentCache = bankCache = null;
		levelsCache = null;
		pendingDropped = 0;
		collectBoxes.clear();
		accountTick = -1;
		accountText = null;
		lastInventory = null;
		lastHistory = null;
		potionsStale = false;
		potionCache = null;
		pouchStale = false;
		pouchCache = seedVaultCache = null;
		pouchSeenMs = seedVaultSeenMs = 0;
		checks.clear();
		reminders.clear();
		remindTick = -1;
		advice = null;
		adviceText = null;
		adviceTick = -1;
		geOpen = false;
		mismatches.clear();
		view = AdviceView.NONE;
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown e)
	{
		// posted off the client thread: hop onto it, and hold the exit until the io thread has written
		final CompletableFuture<Void> written = new CompletableFuture<>();
		clientThread.invoke(() ->
		{
			if (tracker != null && accountDir != null)
			{
				final long now = System.currentTimeMillis();
				if (loggedIn)
				{
					// closing the window ends the session like a logout: the slots are current up to now, and
					// state.json must say logged out, so a reader can tell a closed client from a stalled one
					emit(simple("exit"));
					tracker.markObserved(now);
					loggedIn = false;
					lastLogout = OfferTracker.iso(now);
				}
				exiting = true;
				writeState(now);
			}
			io.submit(() -> written.complete(null));
		});
		e.waitFor(written);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		final GameState s = e.getGameState();
		final long now = System.currentTimeMillis();
		if (s == GameState.LOGGED_IN && !loggedIn)
		{
			loggedIn = true;
			loginTick = client.getTickCount();
			reconciled = false;
			accountTick = -1;
			lastLogin = OfferTracker.iso(now);
			pouchStale = true;        // the pouch varbits arrive with the login; read once they have
			whenReady(() -> emit(simple("login")));
		}
		else if ((s == GameState.LOGIN_SCREEN || s == GameState.LOGIN_SCREEN_AUTHENTICATOR) && loggedIn)
		{
			loggedIn = false;
			lastLogout = OfferTracker.iso(now);
			if (tracker != null)
			{
				tracker.markObserved(now);
				emit(simple("logout"));
				writeState(now);
				tracker.resetSession();
			}
			collectBoxes.clear();
		}
		if (s == GameState.LOGGING_IN || s == GameState.LOGGED_IN)
		{
			ensureAccount();
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
	{
		final GrandExchangeOffer offer = e.getOffer();
		if (offer.getState() == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN)
		{
			// the client blanks every slot while logging in or hopping; those are not real changes
			return;
		}
		observe(e.getSlot(), offer, System.currentTimeMillis());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() == InventoryID.BANK)
		{
			bankCache = container(e.getItemContainer(), true);
			bankFromCache = false;
			bankSeenMs = System.currentTimeMillis();
			potionsStale = true;      // read on the next tick, outside the container event
			dirty = true;
		}
		else if (e.getContainerId() == InventoryID.INV)
		{
			dirty = true;
			inventoryChanged(e.getItemContainer());
		}
		else if (e.getContainerId() == InventoryID.WORN)
		{
			dirty = true;
		}
		else if (e.getContainerId() == InventoryID.SEED_VAULT)
		{
			// the vault's contents reach the client only while it is open: keep the last sight, with its time
			seedVaultCache = container(e.getItemContainer(), false);
			seedVaultSeenMs = System.currentTimeMillis();
			dirty = true;
		}
		else
		{
			onCollectionBox(e.getContainerId(), e.getItemContainer());
		}
	}

	/**
	 * The player's own "Check" on an item (charges, a blowpipe's darts and scales, a sack's contents): the game answers
	 * in chat, so remember which item was asked about. Read-only: the click goes to the game unchanged.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (!config.writeContainers() || !Checks.isCheck(e.getMenuOption()))
		{
			return;
		}
		int id = e.getItemId();
		if (id <= 0 && e.getWidget() != null)
		{
			id = e.getWidget().getItemId();
		}
		if (id <= 0)
		{
			id = wornItemNamed(Text.removeTags(e.getMenuTarget()));
		}
		if (id > 0)
		{
			checks.clicked(id, itemManager.getItemComposition(id).getName(), client.getTickCount());
		}
	}

	/** An equipped item's id from its menu target's name, for an equipment-tab Check that carries no item id. */
	private int wornItemNamed(String name)
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null || name == null)
		{
			return -1;
		}
		for (Item it : worn.getItems())
		{
			if (it.getId() > 0 && name.equalsIgnoreCase(itemManager.getItemComposition(it.getId()).getName()))
			{
				return it.getId();
			}
		}
		return -1;
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (e.getType() != ChatMessageType.GAMEMESSAGE && e.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		if (checks.message(Text.removeTags(e.getMessage()), client.getTickCount(), System.currentTimeMillis()))
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (Stores.isPouchVarbit(e.getVarbitId()))
		{
			pouchStale = true;        // read on the next tick: several pouch varbits change together
		}
	}

	/**
	 * When a slot's order leaves or a new one arrives, what was known of its collection box belongs to the old order:
	 * the client can send the emptied box a while later, and it must not be read as a collection from the new order.
	 */
	private void forgetBoxOnNewOrder(int slot, Map<String, Object> ev)
	{
		final Object type = ev.get("type");
		if ("cleared".equals(type) || "placed".equals(type) || "baseline".equals(type))
		{
			collectBoxes.remove(slot);
		}
	}

	/**
	 * Collection boxes: the client keeps one item container per GE slot holding what is waiting to be collected. It
	 * grows as the offer fills or is aborted and shrinks only when the player collects, so a fall in an item's quantity
	 * is a collection: of the order's item (bought units, or unsold units returned) or of coins. Contents are only sent
	 * while a collection interface is open; the first sight of a box in a session is its baseline.
	 */
	private void onCollectionBox(int id, ItemContainer c)
	{
		int slot = -1;
		for (int i = 0; i < OfferTracker.SLOTS; i++)
		{
			if (GE_COLLECT_INVS[i] == id)
			{
				slot = i;
			}
		}
		if (slot < 0)
		{
			return;
		}
		final Map<Integer, Integer> now = new HashMap<>();
		for (Item it : c == null ? new Item[0] : c.getItems())
		{
			if (it != null && it.getId() > 0 && it.getQuantity() > 0)
			{
				now.merge(it.getId(), it.getQuantity(), Integer::sum);
			}
		}
		final Map<Integer, Integer> before = collectBoxes.put(slot, now);
		if (before == null)
		{
			return;
		}
		final OfferTracker.Offer o = tracker == null ? null : tracker.get(slot);
		final int orderItem = o == null ? -1 : o.itemId;
		int qty = 0;
		long coins = 0;
		final List<Map<String, Object>> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> b : before.entrySet())
		{
			final int gone = b.getValue() - now.getOrDefault(b.getKey(), 0);
			if (gone <= 0)
			{
				continue;
			}
			final int canon = itemManager.canonicalize(b.getKey());
			final Map<String, Object> m = new LinkedHashMap<>();
			m.put("id", b.getKey());
			m.put("name", itemManager.getItemComposition(b.getKey()).getName());
			m.put("quantity", gone);
			items.add(m);
			if (b.getKey() == ItemID.COINS)
			{
				coins += gone;
			}
			else if (canon == orderItem || b.getKey() == orderItem)
			{
				qty += OfferTracker.ownItemCollected(o, gone);
			}
		}
		if (items.isEmpty())
		{
			return;
		}
		final int s = slot;
		final int q = qty;
		final long gp = coins;
		final long t = System.currentTimeMillis();
		whenReady(() ->
		{
			final Map<String, Object> ev = tracker.collect(s, q, gp, items, t);
			if (ev != null)
			{
				emit(ev);
			}
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		final long now = System.currentTimeMillis();
		if (tracker == null)
		{
			ensureAccount();
			return;
		}
		if (loggedIn && !reconciled && loginTick >= 0 && client.getTickCount() - loginTick >= RECONCILE_AFTER_TICKS)
		{
			reconciled = true;
			final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			for (int i = 0; offers != null && i < offers.length && i < OfferTracker.SLOTS; i++)
			{
				if (offers[i] != null && !tracker.seen(i))
				{
					// a slot that got no event at login: whatever this finds is a change the login burst missed
					final List<Map<String, Object>> evs = tracker.observe(i, snapshot(offers[i]), now, true);
					if (!evs.isEmpty())
					{
						reconcileFixes++;
					}
					final int slot = i;
					evs.forEach(ev ->
					{
						forgetBoxOnNewOrder(slot, ev);
						emit(ev);
					});
				}
			}
		}
		if (loggedIn)
		{
			readTradeHistory(now);
		}
		if (potionsStale && loggedIn)
		{
			potionsStale = false;
			readPotionStore(now);
		}
		if (pouchStale && loggedIn)
		{
			pouchStale = false;
			readRunePouch(now);
		}
		final int sinceLogin = client.getTickCount() - loginTick;
		if (loggedIn && config.writeAccount() && sinceLogin >= ACCOUNT_FIRST_TICKS
			&& (accountTick < 0 || client.getTickCount() - accountTick >= ACCOUNT_EVERY_TICKS))
		{
			accountTick = client.getTickCount();
			writeAccount(now);
		}
		if ((dirty && now - lastWriteMs >= FLUSH_MIN_MS) || now - lastWriteMs >= config.heartbeatSeconds() * 1000L)
		{
			writeState(now);
		}
		try
		{
			updateAdvice(now);
		}
		catch (RuntimeException ex)
		{
			view = AdviceView.NONE;
			log.debug("ge-bridge: advice display failed", ex);
		}
		if (loggedIn && reconciled && advice != null && (remindTick < 0 || client.getTickCount() - remindTick >= REMIND_EVERY_TICKS))
		{
			remindTick = client.getTickCount();
			remind(now);
		}
	}

	/**
	 * Reminders whose deadline has passed (0.7.0): one chat line each, and one notification — for a batch (the deadlines
	 * that passed while logged out, all due at the first check after login) a single notification names the count.
	 */
	private Reminders.Settings reminderSettings()
	{
		final Reminders.Settings s = new Reminders.Settings();
		s.grace = config.remindGrace();
		s.dip = config.remindDip();
		s.stall = config.remindStall();
		s.dead = config.remindDead();
		s.collect = config.remindCollect();
		s.collectMinutes = config.remindCollectMinutes();
		return s;
	}

	private void remind(long now)
	{
		final List<Reminders.Due> due = reminders.due(advice, offersNow(), reminderSettings(), now);
		if (due.isEmpty())
		{
			return;
		}
		if (config.remindChat())
		{
			for (Reminders.Due d : due)
			{
				chatMessageManager.queue(QueuedMessage.builder()
					.type(ChatMessageType.GAMEMESSAGE)
					.runeLiteFormattedMessage(reminderLine(d))
					.build());
			}
		}
		notifier.notify(config.remindNotification(), due.size() == 1
			? "GE Bridge: " + due.get(0).text
			: "GE Bridge: " + due.size() + " reminders — " + due.get(0).text + " …");
	}

	static String reminderLine(Reminders.Due d)
	{
		return new ChatMessageBuilder()
			.append(AdviceView.ACT, Text.escapeJagex("GE Bridge reminder (slot " + d.slot + "): " + d.text))
			.build();
	}

	private void observe(int slot, GrandExchangeOffer offer, long now)
	{
		final OfferTracker.Offer snap = snapshot(offer);
		final boolean burst = !loggedIn || client.getTickCount() - loginTick <= LOGIN_BURST_TICKS;
		whenReady(() ->
		{
			for (Map<String, Object> ev : tracker.observe(slot, snap, now, burst))
			{
				forgetBoxOnNewOrder(slot, ev);
				final Object type = ev.get("type");
				if (("placed".equals(type) || "fill".equals(type)) && ev.get("offline") == null)
				{
					ev.put("market", market(snap.itemId));
				}
				if ("cleared".equals(type) || "placed".equals(type) || "baseline".equals(type))
				{
					mismatches.remove(slot);
				}
				emit(ev);
				if ("cancelled".equals(type) && advice != null)
				{
					try
					{
						advice.boughtOut(slot, snap);
					}
					catch (RuntimeException ex)
					{
						log.debug("ge-bridge: advice check failed", ex);
					}
				}
				if ("placed".equals(type))
				{
					try
					{
						if (advice != null)
						{
							advice.markPlaced(snap);
						}
						if (ev.get("offline") == null)
						{
							checkPlaced(slot, snap, now);
						}
					}
					catch (RuntimeException ex)
					{
						// the advice display must never cost an event: the rest of this batch still gets written
						log.debug("ge-bridge: advice check failed", ex);
					}
				}
			}
		});
	}

	/**
	 * The client's own price data for an item when an order is placed or fills: RuneLite's guide price and its actively
	 * traded price. Both are averages the client refreshes now and then, not the live book.
	 */
	private Map<String, Object> market(int itemId)
	{
		final Map<String, Object> m = new LinkedHashMap<>();
		try
		{
			m.put("guide", itemManager.getItemPrice(itemId));
			m.put("active", itemManager.getItemPriceWithSource(itemId, true));
		}
		catch (RuntimeException ex)
		{
			readFailures++;
			log.debug("ge-bridge: no price for {}", itemId, ex);
		}
		return m;
	}

	private OfferTracker.Offer snapshot(GrandExchangeOffer o)
	{
		final int id = o.getItemId();
		final String name = id > 0 ? itemManager.getItemComposition(id).getName() : null;
		return new OfferTracker.Offer(id, name, o.getState().name(), o.getPrice(), o.getTotalQuantity(), o.getQuantitySold(), o.getSpent());
	}

	// ------------------------------------------------------------------ account memory

	/** Runs {@code r} now if the account's memory is loaded, otherwise once it is. */
	private void whenReady(Runnable r)
	{
		if (tracker != null)
		{
			r.run();
			return;
		}
		if (pending.size() < MAX_PENDING)
		{
			pending.add(r);
		}
		else
		{
			pendingDropped++;
			overflowed++;
		}
		ensureAccount();
	}

	private void ensureAccount()
	{
		final long h = client.getAccountHash();
		if (h == -1 || h == accountHash)
		{
			return;
		}
		// a different account (or the first): drop the old memory and load this one's off the client thread
		accountHash = h;
		tracker = null;
		accountDir = null;
		bankCache = null;
		// another account's stores must not be written into this one's state.json if its own has none yet
		potionCache = pouchCache = seedVaultCache = null;
		potionSeenMs = pouchSeenMs = seedVaultSeenMs = 0;
		checks.clear();
		reminders.clear();
		remindTick = -1;
		io.submit(() ->
		{
			try
			{
				final Filepath dir = getPluginDirectory().joinSegment(Long.toString(h));
				dir.createDirectories();
				final Filepath state = dir.joinSegment("state.json");
				final String text = state.exists() ? new String(readAll(state), StandardCharsets.UTF_8) : null;
				clientThread.invoke(() -> install(h, dir, text));
			}
			catch (IOException ex)
			{
				log.warn("ge-bridge: cannot open the data folder", ex);
			}
		});
	}

	private static byte[] readAll(Filepath f) throws IOException
	{
		try (java.io.InputStream in = f.openInputStream())
		{
			return in.readAllBytes();
		}
	}

	private void install(long h, Filepath dir, String text)
	{
		if (h != accountHash)
		{
			return;
		}
		final OfferTracker t = new OfferTracker();
		if (text != null)
		{
			try
			{
				final JsonObject prev = gson.fromJson(text, JsonObject.class);
				final JsonObject offers = prev.has("grandExchange") ? prev.getAsJsonObject("grandExchange").getAsJsonObject("offers") : null;
				for (int i = 0; offers != null && i < OfferTracker.SLOTS; i++)
				{
					if (offers.has(Integer.toString(i)))
					{
						t.restore(i, offerFromJson(offers.getAsJsonObject(Integer.toString(i))));
					}
				}
				if (prev.has("bank") && prev.get("bank").isJsonObject())
				{
					bankCache = prev.get("bank");
					bankFromCache = true;
					bankSeenMs = prev.has("bankLastSeenTimestamp") && !prev.get("bankLastSeenTimestamp").isJsonNull() ? prev.get("bankLastSeenTimestamp").getAsLong() : 0;
				}
				if (prev.has("potionStore") && prev.get("potionStore").isJsonObject())
				{
					potionCache = prev.get("potionStore");
					potionSeenMs = prev.has("potionStoreLastSeenTimestamp") && !prev.get("potionStoreLastSeenTimestamp").isJsonNull()
						? prev.get("potionStoreLastSeenTimestamp").getAsLong() : 0;
				}
				if (prev.has("runePouch") && prev.get("runePouch").isJsonObject())
				{
					pouchCache = prev.get("runePouch");
					pouchSeenMs = longOr(prev, "runePouchLastSeenTimestamp");
				}
				if (prev.has("seedVault") && prev.get("seedVault").isJsonObject())
				{
					seedVaultCache = prev.get("seedVault");
					seedVaultSeenMs = longOr(prev, "seedVaultLastSeenTimestamp");
				}
				checks.restore(prev.get("checks"));
				skillsCache = prev.get("skills");
				inventoryCache = prev.get("inventory");
				equipmentCache = prev.get("equipment");
				if (prev.has("rsn") && !prev.get("rsn").isJsonNull())
				{
					rsn = prev.get("rsn").getAsString();
				}
			}
			catch (RuntimeException ex)
			{
				// an unreadable state.json means no memory: every slot is recorded as a baseline, nothing is booked
				log.warn("ge-bridge: state.json unreadable, starting without slot memory", ex);
			}
		}
		accountDir = dir;
		tracker = t;
		final List<Runnable> run = new ArrayList<>(pending);
		pending.clear();
		run.forEach(Runnable::run);
		if (pendingDropped > 0)
		{
			final Map<String, Object> ev = simple("overflow");
			ev.put("dropped", pendingDropped);
			emit(ev);
			pendingDropped = 0;
		}
		dirty = true;
	}

	static OfferTracker.Offer offerFromJson(JsonObject m)
	{
		final String state = str(m, "state");
		final OfferTracker.Offer o = new OfferTracker.Offer(num(m, "itemId", 0).intValue(), str(m, "itemName"), state,
			num(m, "listedPrice", 0).longValue(), num(m, "totalQuantity", 0).intValue(),
			num(m, "completedQuantity", 0).intValue(), num(m, "spent", 0).longValue());
		o.placedAt = num(m, "placedAt", null);
		o.placedOffline = m.has("placedOffline") && m.get("placedOffline").getAsBoolean();
		o.lastFillAt = num(m, "lastFillAt", null);
		o.collectedQty = num(m, "collectedQuantity", 0).intValue();
		o.collectedCoins = num(m, "collectedCoins", 0);
		o.personal = m.has("personal") && !m.get("personal").isJsonNull() && m.get("personal").getAsBoolean();
		final Long seen = num(m, "observedAt", null);
		o.observedAt = seen == null ? 0 : seen;
		return o;
	}

	private static String str(JsonObject m, String k)
	{
		return m.has(k) && !m.get(k).isJsonNull() ? m.get(k).getAsString() : null;
	}

	private static Long num(JsonObject m, String k, Integer dflt)
	{
		if (m.has(k) && !m.get(k).isJsonNull())
		{
			return m.get(k).getAsLong();
		}
		return dflt == null ? null : dflt.longValue();
	}

	// ------------------------------------------------------------------ output

	private Map<String, Object> simple(String type)
	{
		final long now = System.currentTimeMillis();
		final Map<String, Object> e = new LinkedHashMap<>();
		e.put("ts", OfferTracker.iso(now));
		e.put("t", now);
		e.put("type", type);
		e.put("world", client.getWorld());
		e.put("version", VERSION);
		return e;
	}

	private void emit(Map<String, Object> ev)
	{
		final Filepath dir = accountDir;
		if (dir == null)
		{
			return;
		}
		final String line = gson.toJson(ev) + "\n";
		eventsWritten++;
		if ("anomaly".equals(ev.get("type")))
		{
			anomalies++;
		}
		final long maxBytes = config.maxLogMb() * 1024L * 1024L;
		final long now = System.currentTimeMillis();
		dirty = true;
		io.submit(() ->
		{
			try
			{
				EventLog.append(dir, line, maxBytes, now);
			}
			catch (IOException ex)
			{
				writeFailures.incrementAndGet();
				log.warn("ge-bridge: cannot append an event", ex);
			}
		});
	}

	private java.util.concurrent.Future<?> writeState(long now)
	{
		lastWriteMs = now;
		dirty = false;
		final Filepath dir = accountDir;
		if (dir == null || tracker == null)
		{
			return CompletableFuture.completedFuture(null);
		}
		if (loggedIn && client.getGameState() == GameState.LOGGED_IN)
		{
			tracker.markObserved(now);
			refreshLive();
		}
		final String text = gson.toJson(buildState(now));
		return io.submit(() ->
		{
			try
			{
				final Filepath tmp = dir.joinSegment("state.json.tmp");
				tmp.write(text);
				tmp.moveTo(dir.joinSegment("state.json"), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (IOException ex)
			{
				writeFailures.incrementAndGet();
				log.warn("ge-bridge: cannot write state.json", ex);
			}
		});
	}

	/** Re-read what the client holds while logged in; logged out, the last copies stand. */
	private void refreshLive()
	{
		final Player p = client.getLocalPlayer();
		if (p != null && p.getName() != null)
		{
			rsn = p.getName();
		}
		final JsonObject skills = new JsonObject();
		for (Skill s : Skill.values())
		{
			if ("OVERALL".equals(s.name()))
			{
				continue;
			}
			final JsonObject v = new JsonObject();
			v.addProperty("level", client.getRealSkillLevel(s));
			v.addProperty("boostedLevel", client.getBoostedSkillLevel(s));
			v.addProperty("xp", client.getSkillExperience(s));
			skills.add(s.getName(), v);
		}
		if (client.getTotalLevel() > 0)
		{
			skillsCache = skills;
			levelsCache = new LinkedHashMap<>();
			levelsCache.put("combatLevel", p == null ? null : p.getCombatLevel());
			levelsCache.put("totalLevel", client.getTotalLevel());
			levelsCache.put("totalXp", client.getOverallExperience());
		}
		// logged in, a container the server never sent is an empty one (an empty inventory at login is not sent)
		inventoryCache = container(client.getItemContainer(InventoryID.INV), false);
		equipmentCache = container(client.getItemContainer(InventoryID.WORN), false);
	}

	/** Decanting: potions of one kind swapped for other dose sizes in one inventory change, doses unchanged. */
	private void inventoryChanged(ItemContainer c)
	{
		final Map<Integer, Integer> now = new HashMap<>();
		for (Item it : c == null ? new Item[0] : c.getItems())
		{
			if (it != null && it.getId() > 0 && it.getQuantity() > 0)
			{
				now.merge(it.getId(), it.getQuantity(), Integer::sum);
			}
		}
		final Map<Integer, Integer> before = lastInventory;
		lastInventory = now;
		if (before == null)
		{
			return;
		}
		final List<Decants.Change> changes = new ArrayList<>();
		final java.util.Set<Integer> ids = new java.util.HashSet<>(before.keySet());
		ids.addAll(now.keySet());
		for (int id : ids)
		{
			final int delta = now.getOrDefault(id, 0) - before.getOrDefault(id, 0);
			if (delta != 0)
			{
				changes.add(new Decants.Change(id, itemManager.getItemComposition(id).getName(), delta));
			}
		}
		final long t = System.currentTimeMillis();
		for (Map<String, Object> d : Decants.find(changes))
		{
			final Map<String, Object> ev = new LinkedHashMap<>();
			ev.put("ts", OfferTracker.iso(t));
			ev.put("t", t);
			ev.put("type", "decant");
			ev.putAll(d);
			whenReady(() -> emit(ev));
		}
	}

	/**
	 * The Grand Exchange trade history screen, recorded raw while it is open: each child of its list with its item,
	 * quantity and text. Reading the rows is left to the consumer, so a change to the screen's layout cannot make
	 * the plugin write wrong trades, only rows a reader does not understand. Written only when the contents change.
	 */
	private void readTradeHistory(long now)
	{
		final Widget list = client.getWidget(InterfaceID.GeHistory.LIST);
		if (list == null || list.isHidden())
		{
			return;
		}
		try
		{
			final List<Map<String, Object>> rows = new ArrayList<>();
			final Widget[] kids = list.getDynamicChildren();
			for (int i = 0; kids != null && i < kids.length; i++)
			{
				final Widget w = kids[i];
				if (w == null || w.isHidden())
				{
					continue;
				}
				final String text = w.getText();
				final int item = w.getItemId();
				if ((text == null || text.isEmpty()) && item <= 0)
				{
					continue;
				}
				final Map<String, Object> m = new LinkedHashMap<>();
				m.put("i", i);
				if (item > 0)
				{
					m.put("itemId", item);
					m.put("itemName", itemManager.getItemComposition(item).getName());
					m.put("quantity", w.getItemQuantity());
				}
				if (text != null && !text.isEmpty())
				{
					m.put("text", text);
				}
				rows.add(m);
			}
			if (rows.isEmpty())
			{
				return;
			}
			final String key = rows.toString();
			if (key.equals(lastHistory))
			{
				return;
			}
			lastHistory = key;
			final Map<String, Object> ev = new LinkedHashMap<>();
			ev.put("ts", OfferTracker.iso(now));
			ev.put("t", now);
			ev.put("type", "history");
			ev.put("rows", rows);
			whenReady(() -> emit(ev));
		}
		catch (RuntimeException ex)
		{
			readFailures++;
			log.debug("ge-bridge: trade history unreadable", ex);
		}
	}

	/**
	 * The bank's potion storage, which is not part of the bank container. Read the way RuneLite's bank tags plugin
	 * reads it: each stored potion's doses come from the game's own potion-store script.
	 */
	private void readPotionStore(long now)
	{
		try
		{
			final JsonObject items = new JsonObject();
			long value = 0;
			for (int listId : new int[]{EnumID.POTIONSTORE_POTIONS, EnumID.POTIONSTORE_UNFINISHED_POTIONS})
			{
				for (int potionEnumId : client.getEnum(listId).getIntVals())
				{
					final EnumComposition potion = client.getEnum(potionEnumId);
					client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
					final int doses = client.getIntStack()[0];
					client.runScript(ScriptID.POTIONSTORE_WITHDRAW_DOSES, potionEnumId);
					final int withdraw = client.getIntStack()[0];
					if (doses <= 0 || withdraw <= 0)
					{
						continue;
					}
					final int itemId = potion.getIntValue(withdraw);
					final String name = itemManager.getItemComposition(itemId).getName();
					final double perDose = (double) itemManager.getItemPrice(itemManager.canonicalize(itemId)) / withdraw;
					final JsonObject v = new JsonObject();
					v.addProperty("id", itemId);
					v.addProperty("name", name);
					v.addProperty("doses", doses);
					v.addProperty("withdrawDoses", withdraw);
					v.addProperty("pricePerDose", Math.round(perDose));
					v.addProperty("value", Math.round(perDose * doses));
					items.add(name, v);
					value += Math.round(perDose * doses);
				}
			}
			final JsonObject out = new JsonObject();
			out.addProperty("loaded", true);
			out.addProperty("value", value);
			out.addProperty("itemCount", items.size());
			out.add("items", items);
			potionCache = out;
			potionSeenMs = now;
			dirty = true;
		}
		catch (RuntimeException ex)
		{
			// a change to the game's potion-store scripts must never stop the GE log
			readFailures++;
			log.debug("ge-bridge: potion storage unreadable", ex);
		}
	}

	/** The rune pouch, from the game's pouch varbits and its rune enum (as RuneLite's rune pouch overlay reads them). */
	private void readRunePouch(long now)
	{
		try
		{
			final EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			pouchCache = Stores.runePouch(client::getVarbitValue, runes::getIntValue,
				id -> itemManager.getItemComposition(id).getName(), id -> itemManager.getItemPrice(id));
			pouchSeenMs = now;
			dirty = true;
		}
		catch (RuntimeException ex)
		{
			// a change to the pouch varbits or enum must never stop the GE log
			readFailures++;
			log.debug("ge-bridge: rune pouch unreadable", ex);
		}
	}

	private static long longOr(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsLong() : 0;
	}

	/** account.json: quest states and diary completion, rewritten only when they change. */
	private void writeAccount(long now)
	{
		final Filepath dir = accountDir;
		if (dir == null)
		{
			return;
		}
		final Map<String, Object> quests = new LinkedHashMap<>();
		final Map<String, Object> entries = new LinkedHashMap<>();
		int notStarted = 0;
		int inProgress = 0;
		int finished = 0;
		int unknown = 0;
		try
		{
			for (Quest q : Quest.values())
			{
				QuestState st;
				try
				{
					st = q.getState(client);
				}
				catch (RuntimeException ex)
				{
					st = null;
				}
				final Map<String, Object> m = new LinkedHashMap<>();
				m.put("name", q.getName());
				m.put("state", st == null ? "UNKNOWN" : st.name());
				entries.put(q.name(), m);
				if (st == QuestState.FINISHED)
				{
					finished++;
				}
				else if (st == QuestState.IN_PROGRESS)
				{
					inProgress++;
				}
				else if (st == QuestState.NOT_STARTED)
				{
					notStarted++;
				}
				else
				{
					unknown++;
				}
			}
			quests.put("notStarted", notStarted);
			quests.put("inProgress", inProgress);
			quests.put("finished", finished);
			quests.put("unknown", unknown);
			quests.put("total", entries.size());
			quests.put("entries", entries);
			final Map<String, Object> diaries = AccountData.diaries(client::getVarbitValue);
			final Map<String, Object> body = new LinkedHashMap<>();
			body.put("quests", quests);
			body.put("achievementDiaries", diaries);
			final String key = gson.toJson(body);
			if (key.equals(accountText))
			{
				return;
			}
			accountText = key;
			final Map<String, Object> doc = new LinkedHashMap<>();
			doc.put("schema", SCHEMA);
			doc.put("version", "ge-bridge " + VERSION);
			doc.put("timestamp", now);
			doc.put("timestampIso", OfferTracker.iso(now));
			doc.put("rsn", rsn);
			doc.putAll(body);
			final String text = gson.toJson(doc);
			io.submit(() ->
			{
				try
				{
					final Filepath tmp = dir.joinSegment("account.json.tmp");
					tmp.write(text);
					tmp.moveTo(dir.joinSegment("account.json"), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				}
				catch (IOException ex)
				{
					writeFailures.incrementAndGet();
					log.warn("ge-bridge: cannot write account.json", ex);
				}
			});
		}
		catch (RuntimeException ex)
		{
			readFailures++;
			log.debug("ge-bridge: account data unreadable", ex);
		}
	}

	private JsonObject container(ItemContainer c, boolean skipPlaceholders)
	{
		final JsonObject items = new JsonObject();
		long value = 0;
		int n = 0;
		final Item[] all = c == null ? new Item[0] : c.getItems();
		for (int slot = 0; slot < all.length; slot++)
		{
			final Item it = all[slot];
			if (it == null || it.getId() <= 0 || it.getQuantity() <= 0)
			{
				continue;
			}
			final ItemComposition comp = itemManager.getItemComposition(it.getId());
			if (skipPlaceholders && comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			final long price = itemManager.getItemPrice(itemManager.canonicalize(it.getId()));
			final JsonObject v = new JsonObject();
			v.addProperty("slot", slot);
			v.addProperty("id", it.getId());
			v.addProperty("name", comp.getName());
			v.addProperty("quantity", it.getQuantity());
			v.addProperty("price", price);
			v.addProperty("value", price * it.getQuantity());
			items.add(Integer.toString(slot), v);
			value += price * it.getQuantity();
			n++;
		}
		final JsonObject out = new JsonObject();
		out.addProperty("loaded", true);
		out.addProperty("value", value);
		out.addProperty("itemCount", n);
		out.add("items", items);
		return out;
	}

	private JsonObject buildState(long now)
	{
		final JsonObject s = new JsonObject();
		s.addProperty("schema", SCHEMA);
		s.addProperty("version", "ge-bridge " + VERSION);
		s.addProperty("timestamp", now);
		s.addProperty("timestampIso", OfferTracker.iso(now));
		s.addProperty("rsn", rsn);
		s.addProperty("accountHash", Long.toString(accountHash));
		s.addProperty("world", client.getWorld());
		s.addProperty("gameState", exiting ? "EXITED" : client.getGameState().name());
		s.addProperty("loggedIn", loggedIn);
		s.addProperty("lastLogin", lastLogin);
		s.addProperty("lastLogout", lastLogout);
		s.addProperty("heartbeatSeconds", config.heartbeatSeconds());
		final JsonObject sections = new JsonObject();
		sections.addProperty("skills", config.writeSkills());
		sections.addProperty("containers", config.writeContainers());
		sections.addProperty("bank", config.writeBank());
		s.add("sections", sections);
		final JsonObject health = new JsonObject();
		health.addProperty("since", OfferTracker.iso(healthSince));
		health.addProperty("eventsWritten", eventsWritten);
		health.addProperty("writeFailures", writeFailures.get());
		health.addProperty("readFailures", readFailures);
		health.addProperty("anomalies", anomalies);
		health.addProperty("reconcileFixes", reconcileFixes);
		health.addProperty("overflowed", overflowed);
		health.addProperty("pending", pending.size());
		s.add("health", health);
		if (config.writeSkills())
		{
			if (levelsCache != null)
			{
				levelsCache.forEach((k, v) -> s.add(k, gson.toJsonTree(v)));
			}
			s.add("skills", skillsCache);
		}
		if (config.writeContainers())
		{
			s.addProperty("inventoryLoaded", inventoryCache != null);
			s.add("inventory", inventoryCache);
			s.addProperty("equipmentLoaded", equipmentCache != null);
			s.add("equipment", equipmentCache);
			s.add("checks", checks.toJson());
		}
		if (config.writeBank())
		{
			s.addProperty("bankLoaded", bankCache != null);
			s.addProperty("bankFromCache", bankFromCache);
			s.addProperty("bankLastSeenTimestamp", bankSeenMs > 0 ? bankSeenMs : null);
			s.add("bank", bankCache);
			s.add("potionStore", potionCache);
			s.addProperty("potionStoreLastSeenTimestamp", potionSeenMs > 0 ? potionSeenMs : null);
			s.add("runePouch", pouchCache);
			s.addProperty("runePouchLastSeenTimestamp", pouchSeenMs > 0 ? pouchSeenMs : null);
			s.add("seedVault", seedVaultCache);
			s.addProperty("seedVaultLastSeenTimestamp", seedVaultSeenMs > 0 ? seedVaultSeenMs : null);
		}
		s.add("grandExchange", gson.toJsonTree(tracker.toJson()));
		return s;
	}

	// ------------------------------------------------------------------ advice display

	AdviceView adviceView()
	{
		return view;
	}

	private boolean isGeOpen()
	{
		final Widget w = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
		return w != null && !w.isHidden();
	}

	/** Each tick: re-read advice.json now and then while the Grand Exchange is open, and rebuild what the overlays draw. */
	private void updateAdvice(long now)
	{
		final boolean open = loggedIn && isGeOpen();
		if (open && accountDir != null && config.showAdvice()
			&& (!geOpen || adviceTick < 0 || client.getTickCount() - adviceTick >= ADVICE_EVERY_TICKS))
		{
			adviceTick = client.getTickCount();
			loadAdvice();
		}
		geOpen = open;
		view = open && config.showAdvice() ? buildView(now) : AdviceView.NONE;
	}

	private void loadAdvice()
	{
		final Filepath dir = accountDir;
		io.submit(() ->
		{
			String text = null;
			try
			{
				final Filepath f = dir.joinSegment("advice.json");
				text = f.exists() ? new String(readAll(f), StandardCharsets.UTF_8) : null;
			}
			catch (IOException ex)
			{
				log.debug("ge-bridge: advice.json unreadable", ex);
			}
			final String t = text;
			clientThread.invoke(() -> applyAdvice(dir, t));
		});
	}

	private void applyAdvice(Filepath dir, String text)
	{
		if (dir != accountDir || (text != null && text.equals(adviceText)))
		{
			return;
		}
		adviceText = text;
		advice = null;
		if (text == null)
		{
			return;
		}
		try
		{
			final Advice a = gson.fromJson(text, Advice.class);
			advice = a != null && a.usable() ? a : null;
		}
		catch (JsonParseException ex)
		{
			readFailures++;
			log.debug("ge-bridge: advice.json is not valid", ex);
		}
	}

	/** The advice, if it is loaded and young enough to show. */
	private Advice freshAdvice(long now)
	{
		return advice != null && now - advice.generatedAt <= config.adviceMaxAgeHours() * 3_600_000L ? advice : null;
	}

	private OfferTracker.Offer[] offersNow()
	{
		final OfferTracker.Offer[] out = new OfferTracker.Offer[OfferTracker.SLOTS];
		for (int i = 0; tracker != null && i < OfferTracker.SLOTS; i++)
		{
			out[i] = tracker.get(i);
		}
		return out;
	}

	/** An order just placed that differs from the advice for its item: flag the slot and say so in the chat box. */
	private void checkPlaced(int slot, OfferTracker.Offer o, long now)
	{
		final Advice a = config.showAdvice() ? freshAdvice(now) : null;
		final String diff = a == null ? null : a.placedMismatch(o);
		if (diff == null)
		{
			return;
		}
		mismatches.put(slot, diff);
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(warning(slot, diff))
			.build());
	}

	/**
	 * The chat line for a placed order that differs from the advice. The colour goes in through the builder's colour
	 * method: its plain append escapes tags, which printed them as text (0.6.0).
	 */
	static String warning(int slot, String diff)
	{
		return new ChatMessageBuilder()
			.append(AdviceView.WARN, Text.escapeJagex("GE Bridge: slot " + slot + " differs from the advice: " + diff))
			.build();
	}

	private AdviceView buildView(long now)
	{
		if (tracker == null || advice == null)
		{
			return AdviceView.NONE;
		}
		final OfferTracker.Offer[] offers = offersNow();
		Advice.Check check = null;
		if (freshAdvice(now) != null)
		{
			final int selected = client.getVarbitValue(VarbitID.GE_SELECTEDSLOT) - 1;
			final Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
			final int item = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
			if (selected >= 0 && selected < OfferTracker.SLOTS && setup != null && !setup.isHidden()
				&& (offers[selected] == null || offers[selected].isEmpty()) && item > 0)
			{
				final String side = client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) == 1 ? "sell" : "buy";
				check = advice.check(itemManager.canonicalize(item), side, client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY), offers);
			}
		}
		final Map<Integer, Reminders.Clock> clocks = config.remindPanel() ? Reminders.clocks(advice, offers, reminderSettings(), now)
			: java.util.Collections.emptyMap();
		return AdviceView.build(advice, offers, mismatches, check, now, config.adviceMaxAgeHours() * 3_600_000L, config.highlightSlots(), clocks);
	}

	/** "Mark personal" on a Grand Exchange slot's right-click menu. Client-side only: it writes a tag event. */
	@Subscribe
	public void onMenuOpened(MenuOpened e)
	{
		if (!config.personalMenu() || tracker == null || !geOpen)
		{
			return;
		}
		for (MenuEntry me : e.getMenuEntries())
		{
			final Widget w = me.getWidget();
			for (int slot = 0; w != null && slot < OfferTracker.SLOTS; slot++)
			{
				final OfferTracker.Offer o = tracker.get(slot);
				if (w.getId() != SlotOverlay.SLOT_WIDGETS[slot] || o == null || o.isEmpty())
				{
					continue;
				}
				final int s = slot;
				final boolean mark = !o.personal;
				// index 1: just above Cancel, never the left-click option
				client.getMenu().createMenuEntry(1)
					.setOption(mark ? "Mark personal" : "Unmark personal")
					.setTarget(ColorUtil.wrapWithColorTag(o.item, AdviceView.ACT))
					.setType(MenuAction.RUNELITE)
					.onClick(x -> togglePersonal(s, mark));
				return;
			}
		}
	}

	private void togglePersonal(int slot, boolean personal)
	{
		if (tracker == null)
		{
			return;
		}
		final Map<String, Object> ev = tracker.tag(slot, personal, System.currentTimeMillis());
		if (ev != null)
		{
			if (personal)
			{
				mismatches.remove(slot);
			}
			emit(ev);
		}
	}
}

package io.github.y5c.gebridge;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Turns the client's Grand Exchange slot states into an event log.
 *
 * <p>Holds the last known offer in each of the eight slots and diffs every new
 * observation against it. The memory survives logouts (it is restored from
 * state.json), so a change first seen at login is an offline change: it is
 * flagged {@code offline} with {@code since} = the last time the slot was
 * observed, because its real time lies somewhere in that window.
 *
 * <p>Pure logic, no client types: every method runs on the client thread.
 */
final class OfferTracker
{
	static final int SLOTS = 8;

	static final class Offer
	{
		int itemId;
		String item;
		String state;
		long price;
		int total;
		int done;
		long spent;
		Long placedAt;
		boolean placedOffline;
		Long lastFillAt;
		long observedAt;
		// taken out of the collection box while this order was in the slot: the order's own item, and coins
		int collectedQty;
		long collectedCoins;
		// the player marked this order as their own (not for their tools' accounting); follows the order until it leaves
		boolean personal;

		Offer(int itemId, String item, String state, long price, int total, int done, long spent)
		{
			this.itemId = itemId;
			this.item = item;
			this.state = state;
			this.price = price;
			this.total = total;
			this.done = done;
			this.spent = spent;
		}

		boolean isEmpty()
		{
			return state == null || "EMPTY".equals(state) || itemId <= 0;
		}

		String side()
		{
			return side(state);
		}

		static String side(String state)
		{
			switch (state == null ? "" : state)
			{
				case "BUYING":
				case "BOUGHT":
				case "CANCELLED_BUY":
					return "buy";
				case "SELLING":
				case "SOLD":
				case "CANCELLED_SELL":
					return "sell";
				default:
					return null;
			}
		}

		/** The same order: a slot keeps its item, side, price and quantity until it is collected. */
		boolean sameOrder(Offer o)
		{
			return o != null && !isEmpty() && !o.isEmpty() && itemId == o.itemId && price == o.price
				&& total == o.total && side().equals(o.side());
		}
	}

	private final Offer[] slots = new Offer[SLOTS];
	private final boolean[] seen = new boolean[SLOTS];
	// when each slot was last observed before this session began: the start of the window for an offline change
	private final Long[] sessionStart = new Long[SLOTS];

	Offer get(int slot)
	{
		return slots[slot];
	}

	boolean seen(int slot)
	{
		return seen[slot];
	}

	/** Install remembered state (from the last state.json); it counts as not yet seen this session. */
	void restore(int slot, Offer o)
	{
		slots[slot] = o;
		seen[slot] = false;
		sessionStart[slot] = o == null ? null : o.observedAt;
	}

	/** A logout: the next observation of every slot is a first sight again. */
	void resetSession()
	{
		for (int i = 0; i < SLOTS; i++)
		{
			seen[i] = false;
			sessionStart[i] = slots[i] == null ? null : slots[i].observedAt;
		}
	}

	/** While logged in, a slot seen this session is known to be current up to {@code now}. */
	void markObserved(long now)
	{
		for (int i = 0; i < SLOTS; i++)
		{
			if (seen[i] && slots[i] != null)
			{
				slots[i].observedAt = now;
			}
		}
	}

	List<Map<String, Object>> observe(int slot, Offer snap, long now)
	{
		return observe(slot, snap, now, false);
	}

	/**
	 * {@code loginBurst}: the client is still receiving the slots after a login. It can show a slot unchanged first and
	 * deliver the fills made while logged out a second later, so a change in the burst is offline even when the slot
	 * was already seen this session.
	 */
	List<Map<String, Object>> observe(int slot, Offer snap, long now, boolean loginBurst)
	{
		if (slot < 0 || slot >= SLOTS || snap == null)
		{
			return Collections.emptyList();
		}
		final Offer prev = slots[slot];
		final boolean offline = (!seen[slot] || loginBurst) && prev != null && sessionStart[slot] != null;
		final Long since = offline ? sessionStart[slot] : null;
		seen[slot] = true;
		snap.observedAt = now;
		final List<Map<String, Object>> out = new ArrayList<>();

		if (prev == null)
		{
			// nothing remembered for this slot (first run): record what is there, book nothing
			if (!snap.isEmpty())
			{
				out.add(event("baseline", slot, snap, now, false, null));
			}
			slots[slot] = snap;
			return out;
		}

		if (!snap.sameOrder(prev))
		{
			if (!prev.isEmpty())
			{
				Map<String, Object> e = event("cleared", slot, prev, now, offline, since);
				if (!isTerminal(prev.state))
				{
					// left the slot without us seeing it finish: any fills after `since` are unknown
					e.put("unobserved", true);
				}
				out.add(e);
			}
			if (!snap.isEmpty())
			{
				snap.placedAt = now;
				snap.placedOffline = offline;
				out.add(event("placed", slot, snap, now, offline, since));
				if (snap.done > 0)
				{
					snap.lastFillAt = now;
					out.add(fill(slot, snap, snap.done, snap.spent, now, offline, since));
				}
				addStateChange(out, slot, null, snap, now, offline, since);
			}
			slots[slot] = snap;
			return out;
		}

		snap.placedAt = prev.placedAt;
		snap.placedOffline = prev.placedOffline;
		snap.lastFillAt = prev.lastFillAt;
		snap.collectedQty = prev.collectedQty;
		snap.collectedCoins = prev.collectedCoins;
		snap.personal = prev.personal;
		final int d = snap.done - prev.done;
		if (d > 0)
		{
			snap.lastFillAt = now;
			out.add(fill(slot, snap, d, snap.spent - prev.spent, now, offline, since));
		}
		else if (d < 0)
		{
			Map<String, Object> e = event("anomaly", slot, snap, now, offline, since);
			e.put("note", "completed quantity went down from " + prev.done);
			out.add(e);
		}
		addStateChange(out, slot, prev.state, snap, now, offline, since);
		slots[slot] = snap;
		return out;
	}

	/**
	 * Items taken out of a slot's collection box. {@code qty} is the order's own item (units bought, or unsold units
	 * returned), {@code coins} the coins (sale proceeds, or a buy's refund). Returns the event, or null when the slot
	 * holds no order to attribute it to.
	 */
	Map<String, Object> collect(int slot, int qty, long coins, List<Map<String, Object>> items, long now)
	{
		final Offer o = slot >= 0 && slot < SLOTS ? slots[slot] : null;
		if (o == null || o.isEmpty() || (qty <= 0 && coins <= 0))
		{
			return null;
		}
		o.collectedQty += Math.max(0, qty);
		o.collectedCoins += Math.max(0, coins);
		final Map<String, Object> e = event("collected", slot, o, now, false, null);
		e.put("qty", qty);
		e.put("coins", coins);
		e.put("items", items);
		e.put("collectedQty", o.collectedQty);
		e.put("collectedCoins", o.collectedCoins);
		return e;
	}

	/**
	 * The player marks (or unmarks) the order in a slot as personal. Returns the {@code tag} event, or null when the slot
	 * holds no order.
	 */
	Map<String, Object> tag(int slot, boolean personal, long now)
	{
		final Offer o = slot >= 0 && slot < SLOTS ? slots[slot] : null;
		if (o == null || o.isEmpty())
		{
			return null;
		}
		o.personal = personal;
		final Map<String, Object> e = event("tag", slot, o, now, false, null);
		e.put("personal", personal);
		return e;
	}

	/**
	 * How much of a fall in the order's own item in its collection box counts as collected from that order. A buy
	 * puts bought units in the box; a sell only gets its item back when it is cancelled. Anything else is the box
	 * of an earlier order in the slot arriving late, and is not this order's.
	 */
	static int ownItemCollected(Offer o, int gone)
	{
		if (o == null || o.isEmpty() || gone <= 0)
		{
			return 0;
		}
		return "buy".equals(o.side()) || o.state.startsWith("CANCELLED") ? gone : 0;
	}

	private static boolean isTerminal(String state)
	{
		return state != null && (state.equals("BOUGHT") || state.equals("SOLD") || state.startsWith("CANCELLED"));
	}

	private static void addStateChange(List<Map<String, Object>> out, int slot, String before, Offer snap, long now, boolean offline, Long since)
	{
		if (snap.state.equals(before))
		{
			return;
		}
		if (snap.state.equals("BOUGHT") || snap.state.equals("SOLD"))
		{
			out.add(event("completed", slot, snap, now, offline, since));
		}
		else if (snap.state.startsWith("CANCELLED"))
		{
			out.add(event("cancelled", slot, snap, now, offline, since));
		}
	}

	private static Map<String, Object> fill(int slot, Offer o, int qty, long gp, long now, boolean offline, Long since)
	{
		Map<String, Object> e = event("fill", slot, o, now, offline, since);
		e.put("qty", qty);
		e.put("gp", gp);
		return e;
	}

	static Map<String, Object> event(String type, int slot, Offer o, long now, boolean offline, Long since)
	{
		Map<String, Object> e = new LinkedHashMap<>();
		e.put("ts", iso(now));
		e.put("t", now);
		e.put("type", type);
		e.put("slot", slot);
		e.put("itemId", o.itemId);
		e.put("item", o.item);
		e.put("side", o.side());
		e.put("state", o.state);
		e.put("price", o.price);
		e.put("total", o.total);
		e.put("done", o.done);
		e.put("spent", o.spent);
		if (offline)
		{
			e.put("offline", true);
			e.put("since", since == null ? null : iso(since));
		}
		return e;
	}

	static String iso(long ms)
	{
		return Instant.ofEpochMilli(ms).toString();
	}

	/** The slots for state.json, in the shape the old Local Data Exporter used (plus timing fields). */
	Map<String, Object> toJson()
	{
		Map<String, Object> offers = new LinkedHashMap<>();
		int active = 0;
		boolean any = false;
		for (int i = 0; i < SLOTS; i++)
		{
			Offer o = slots[i];
			if (o == null)
			{
				continue;
			}
			any = true;
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("slot", i);
			m.put("state", o.isEmpty() ? "EMPTY" : o.state);
			m.put("observedAt", o.observedAt);
			m.put("seenThisSession", seen[i]);
			if (!o.isEmpty())
			{
				active++;
				m.put("itemId", o.itemId);
				m.put("itemName", o.item);
				m.put("listedPrice", o.price);
				m.put("totalQuantity", o.total);
				m.put("completedQuantity", o.done);
				m.put("remainingQuantity", o.total - o.done);
				m.put("spent", o.spent);
				m.put("placedAt", o.placedAt);
				m.put("placedOffline", o.placedOffline);
				m.put("lastFillAt", o.lastFillAt);
				m.put("collectedQuantity", o.collectedQty);
				m.put("collectedCoins", o.collectedCoins);
				m.put("personal", o.personal);
			}
			offers.put(Integer.toString(i), m);
		}
		Map<String, Object> ge = new LinkedHashMap<>();
		ge.put("loaded", any);
		ge.put("activeCount", active);
		ge.put("offers", offers);
		return ge;
	}
}

package io.github.y5c.gebridge;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The advice's own deadlines for the orders it names (0.7.0): an ask's grace before a trim, the end of a held price dip, a
 * bid with no fills for the tool's stall or dead time, and a completed buy left uncollected. {@link #clocks} says, per
 * slot, which deadline applies, when it falls due and what the advice would then do — the panel shows it as a countdown
 * or as due (0.7.1); {@link #due} turns the ones that have passed into reminders, once per order. Only orders the advice
 * names are timed, never one marked personal. Display only: it never acts. Pure: offers, advice and time are passed in.
 */
final class Reminders
{
	/** An ask counts as unsold only without a fill in this long (the tool's own "still filling" window). */
	static final long FILLING_MS = 2 * 3_600_000L;
	/** Prices older than this carry the advice's age, so a stale price reads as one. */
	static final long STALE_MS = 3 * 3_600_000L;

	static final class Settings
	{
		boolean grace = true;
		boolean dip = true;
		boolean stall = true;
		boolean dead = true;
		boolean collect = true;
		int collectMinutes = 10;
	}

	/** One slot's deadline: its kind, when it falls due, whether it has, the action for the panel, the reminder's text. */
	static final class Clock
	{
		final String kind;
		final long at;
		final boolean due;
		final String action;
		final String notice;
		final String key;

		Clock(String kind, long at, long now, String action, String notice, String key)
		{
			this.kind = kind;
			this.at = at;
			this.due = now >= at;
			this.action = action;
			this.notice = notice;
			this.key = key;
		}
	}

	static final class Due
	{
		final int slot;
		final String kind;
		final String text;

		Due(int slot, String kind, String text)
		{
			this.slot = slot;
			this.kind = kind;
			this.text = text;
		}
	}

	private final Set<String> fired = new HashSet<>();

	/** Per slot, the deadline that applies now (at most one), whether it has passed or not. */
	static Map<Integer, Clock> clocks(Advice a, OfferTracker.Offer[] offers, Settings s, long now)
	{
		final Map<Integer, Clock> out = new LinkedHashMap<>();
		if (a == null)
		{
			return out;
		}
		final String stale = now - a.generatedAt > STALE_MS ? " (advice " + Advice.age(now - a.generatedAt) + " old)" : "";
		final Advice.Deadlines d = a.deadlines;
		for (int i = 0; i < offers.length; i++)
		{
			final OfferTracker.Offer o = offers[i];
			if (o == null || o.isEmpty() || o.personal || o.placedAt == null)
			{
				continue;
			}
			final Advice.Slot sl = a.forSlot(i, o);
			final Advice.Order order = a.orderFor(o);
			if (sl == null && order == null)
			{
				continue;      // an order the advice never named: not the tool's to time
			}
			final long placed = o.placedAt;
			final String id = i + "|" + o.itemId + "|" + o.side() + "|" + o.price + "|" + placed + "|";
			Clock c = null;
			switch (o.state)
			{
				case "SELLING":
				{
					// a held dip has its own clock: its end is the one trim, so the grace does not also run for it
					if (sl != null && sl.holdUntil != null)
					{
						if (s.dip)
						{
							final String to = sl.holdTrimTo != null ? Advice.fmt(sl.holdTrimTo) : null;
							c = new Clock("dip", sl.holdUntil, now, to != null ? "trim " + to : "trim",
								o.item + ": the dip hold is over — trim toward " + (to != null ? to + stale : "the 2 h level (check in)"), id + "dip");
						}
					}
					else if (s.grace && d != null && d.askGraceHours != null && o.done < o.total)
					{
						// due once the grace has run AND the ask has gone 2 h without a sale
						final long at = Math.max(placed + hours(d.askGraceHours), o.lastFillAt != null ? o.lastFillAt + FILLING_MS : 0);
						final String to = sl != null && sl.trimTo != null ? Advice.fmt(sl.trimTo) : null;
						c = new Clock("grace", at, now, to != null ? "trim " + to : "trim (check in)",
							o.item + ": " + (o.done == 0 ? "unsold" : "no sale in 2 h") + " " + trimHours(d.askGraceHours) + " h after listing — "
								+ (to != null ? "trim to " + to + stale : "a check-in would trim it"), id + "grace");
					}
					break;
				}
				case "BUYING":
				{
					final long last = o.lastFillAt != null ? o.lastFillAt : placed;
					final Long dead = s.dead && d != null && d.bidDeadHours != null && o.done == 0 ? placed + hours(d.bidDeadHours) : null;
					final Long stall = s.stall && d != null && d.bidStallHours != null ? last + hours(d.bidStallHours) : null;
					if (dead != null && now >= dead)
					{
						c = new Clock("dead", dead, now, "cancel", o.item + ": no fills in " + trimHours(d.bidDeadHours)
							+ " h — the advice cancels bids this quiet", id + "dead");
					}
					else if (stall != null)
					{
						// what the advice said a stall brings (0.7.3): cancel, or the price to re-place at
						final boolean cancel = sl != null && Boolean.TRUE.equals(sl.stallCancel);
						final String to = !cancel && sl != null && sl.replaceTo != null ? Advice.fmt(sl.replaceTo) : null;
						c = new Clock("stall", stall, now, cancel ? "cancel" : to != null ? "re-place " + to : "re-place (check in)",
							o.item + ": no fills in " + trimHours(d.bidStallHours) + " h — "
								+ (cancel ? "the advice cancels it" : to != null ? "re-place at " + to + stale : "a check-in would re-place or cancel it"),
							id + "stall");
					}
					else if (dead != null)
					{
						c = new Clock("dead", dead, now, "cancel", null, id + "dead");
					}
					break;
				}
				case "BOUGHT":
				{
					if (s.collect)
					{
						final long done = o.lastFillAt != null ? o.lastFillAt : placed;
						final Long at = sl != null && sl.listAt != null ? sl.listAt : order != null ? order.listLater : null;
						c = new Clock("collect", done + s.collectMinutes * 60_000L, now, at != null ? "list " + Advice.fmt(at) : "list",
							o.item + ": bought " + Advice.fmt(o.total) + " — collect" + (at != null ? " and list at " + Advice.fmt(at) + stale : " and list"),
							id + "collect");
					}
					break;
				}
				default:
					break;
			}
			if (c != null)
			{
				out.put(i, c);
			}
		}
		return out;
	}

	/** The reminders now due that have not fired yet; each is then marked fired. */
	List<Due> due(Advice a, OfferTracker.Offer[] offers, Settings s, long now)
	{
		final List<Due> out = new ArrayList<>();
		for (Map.Entry<Integer, Clock> e : clocks(a, offers, s, now).entrySet())
		{
			final Clock c = e.getValue();
			if (c.due && c.notice != null && fired.add(c.key))
			{
				out.add(new Due(e.getKey(), c.kind, c.notice));
			}
		}
		return out;
	}

	void clear()
	{
		fired.clear();
	}

	/** "2h10m", "45m", "<1m": the time left before a deadline, compact enough for one panel line. */
	static String left(long ms)
	{
		final long m = ms / 60_000;
		if (m < 1)
		{
			return "<1m";
		}
		return m < 60 ? m + "m" : (m / 60) + "h" + (m % 60) + "m";
	}

	private static long hours(double h)
	{
		return (long) (h * 3_600_000L);
	}

	private static String trimHours(double h)
	{
		return h == Math.rint(h) ? Long.toString((long) h) : Double.toString(h);
	}
}

package io.github.y5c.gebridge;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Outlines the Grand Exchange slots the advice says to act on. Draws only; the slots' click areas are untouched. */
final class SlotOverlay extends Overlay
{
	static final int[] SLOT_WIDGETS = {InterfaceID.GeOffers.INDEX_0, InterfaceID.GeOffers.INDEX_1, InterfaceID.GeOffers.INDEX_2,
		InterfaceID.GeOffers.INDEX_3, InterfaceID.GeOffers.INDEX_4, InterfaceID.GeOffers.INDEX_5, InterfaceID.GeOffers.INDEX_6,
		InterfaceID.GeOffers.INDEX_7};

	private final Client client;
	private final GeBridgePlugin plugin;

	@Inject
	SlotOverlay(Client client, GeBridgePlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final Map<Integer, Color> slots = plugin.adviceView().slots;
		if (slots.isEmpty())
		{
			return null;
		}
		g.setStroke(new BasicStroke(2));
		for (Map.Entry<Integer, Color> e : slots.entrySet())
		{
			final Widget w = client.getWidget(SLOT_WIDGETS[e.getKey()]);
			if (w == null || w.isHidden())
			{
				continue;
			}
			final Rectangle r = w.getBounds();
			g.setColor(e.getValue());
			g.drawRect(r.x + 1, r.y + 1, r.width - 2, r.height - 2);
		}
		return null;
	}
}

package io.github.y5c.gebridge;

import com.google.gson.JsonObject;
import java.util.function.IntToLongFunction;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarbitID;

/**
 * Item stores outside the bank container that state.json reports (0.6.4): the rune pouch, read from the game's own
 * pouch varbits the way RuneLite's rune pouch overlay reads them. Pure: the varbit read, the rune lookup and the item
 * name and price lookups are passed in, so the layout is testable without a client.
 */
final class Stores
{
	/** One varbit pair per pouch slot: the rune's type (an index into the game's rune enum) and how many. */
	static final int[] POUCH_TYPE = {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6};
	static final int[] POUCH_QUANTITY = {VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6};

	private Stores()
	{
	}

	static boolean isPouchVarbit(int varbit)
	{
		for (int i = 0; i < POUCH_TYPE.length; i++)
		{
			if (POUCH_TYPE[i] == varbit || POUCH_QUANTITY[i] == varbit)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The rune pouch in the bank-container layout ({loaded, value, itemCount, items}), keyed by pouch slot. An empty
	 * slot (type 0 or quantity 0), or a type the rune enum does not map to an item, is left out.
	 *
	 * @param varbit    the game's varbit value for an id
	 * @param runeItem  the rune enum: pouch rune type → item id (0 or less: unknown)
	 * @param name      item id → name
	 * @param price     item id → guide price per rune
	 */
	static JsonObject runePouch(IntUnaryOperator varbit, IntUnaryOperator runeItem, IntFunction<String> name, IntToLongFunction price)
	{
		final JsonObject items = new JsonObject();
		long value = 0;
		for (int slot = 0; slot < POUCH_TYPE.length; slot++)
		{
			final int type = varbit.applyAsInt(POUCH_TYPE[slot]);
			final int qty = varbit.applyAsInt(POUCH_QUANTITY[slot]);
			if (type <= 0 || qty <= 0)
			{
				continue;
			}
			final int id = runeItem.applyAsInt(type);
			if (id <= 0)
			{
				continue;
			}
			final long each = price.applyAsLong(id);
			final JsonObject v = new JsonObject();
			v.addProperty("slot", slot);
			v.addProperty("id", id);
			v.addProperty("name", name.apply(id));
			v.addProperty("quantity", qty);
			v.addProperty("price", each);
			v.addProperty("value", each * qty);
			items.add(Integer.toString(slot), v);
			value += each * qty;
		}
		final JsonObject out = new JsonObject();
		out.addProperty("loaded", true);
		out.addProperty("value", value);
		out.addProperty("itemCount", items.size());
		out.add("items", items);
		return out;
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class AccountDataTest
{
	@Test
	@SuppressWarnings("unchecked")
	public void karamjaNeedsTwoAndTheRestNeedOne()
	{
		// every varbit at 1: Karamja's easy/medium/hard (which the game marks complete at 2) are not complete
		Map<String, Object> d = AccountData.diaries(v -> 1);
		Map<String, Object> karamja = (Map<String, Object>) ((Map<String, Object>) d.get("regions")).get("karamja");
		assertEquals(false, ((Map<String, Object>) karamja.get("easy")).get("complete"));
		assertEquals(true, ((Map<String, Object>) karamja.get("elite")).get("complete"));
		assertEquals(45, d.get("completedTierCount"));
		assertEquals(48, d.get("totalTierCount"));

		d = AccountData.diaries(v -> v == VarbitID.ATJUN_EASY_DONE || v == VarbitID.ATJUN_MED_DONE || v == VarbitID.ATJUN_HARD_DONE ? 2 : 1);
		assertEquals(48, d.get("completedTierCount"));
		assertEquals(100.0, d.get("completionPercent"));

		d = AccountData.diaries(v -> 0);
		assertEquals(0, d.get("completedTierCount"));
		assertEquals(12, ((Map<String, Object>) d.get("regions")).size());
	}
