package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonObject;
import org.junit.Test;

public class ChecksTest
{
	@Test
	public void checkOptionsAreRecognised()
	{
		assertTrue(Checks.isCheck("Check"));
		assertTrue(Checks.isCheck("Check-charges"));
		assertTrue(Checks.isCheck(" check "));
		assertFalse(Checks.isCheck("Uncharge"));
		assertFalse(Checks.isCheck(null));
	}

	@Test
	public void theAnswerIsKeptWithItsItemAndTime()
	{
		final Checks c = new Checks();
		c.clicked(12926, "Toxic blowpipe", 100);
		assertTrue(c.message("Darts: Dragon dart x 1,234. Scales: 5,678 (35.0%).", 101, 5000L));
		final JsonObject v = c.toJson().getAsJsonObject("12926");
		assertEquals("Toxic blowpipe", v.get("name").getAsString());
		assertEquals(1, v.getAsJsonArray("lines").size());
		assertEquals(5000L, v.get("timestamp").getAsLong());
	}

	@Test
	public void aManyLineAnswerIsJoinedAndANewCheckReplacesIt()
	{
		final Checks c = new Checks();
		c.clicked(13226, "Herb sack", 10);
		c.message("You look in your herb sack and see:", 11, 1L);
		c.message("12 x Grimy ranarr weed", 11, 1L);
		assertEquals(2, c.toJson().getAsJsonObject("13226").getAsJsonArray("lines").size());
		c.clicked(13226, "Herb sack", 50);
		c.message("The herb sack is empty.", 51, 2L);
		assertEquals(1, c.toJson().getAsJsonObject("13226").getAsJsonArray("lines").size());
	}

	@Test
	public void messagesOutsideTheWindowOrWithoutAClickAreIgnored()
	{
		final Checks c = new Checks();
		assertFalse(c.message("You feel a slight tingle.", 5, 1L));      // no click yet
		c.clicked(11905, "Trident of the seas", 10);
		assertFalse(c.message("Your trident has 2,500 charges.", 10 + Checks.WINDOW_TICKS + 1, 1L));
		assertEquals(0, c.toJson().size());
	}

	@Test
	public void aRestartKeepsTheLastAnswersAndTheListIsBounded()
	{
		final Checks a = new Checks();
		a.clicked(1, "A", 0);
		a.message("Your A has 5 charges.", 1, 1L);
		final Checks b = new Checks();
		b.restore(a.toJson());
		assertEquals("A", b.toJson().getAsJsonObject("1").get("name").getAsString());
		for (int i = 2; i < 2 + Checks.MAX_ITEMS; i++)
		{
			b.clicked(i, "X", i);
			b.message("x", i, 1L);
		}
		assertEquals(Checks.MAX_ITEMS, b.toJson().size());
		assertFalse(b.toJson().has("1"));                                // the oldest answer goes first
		b.clear();
		assertEquals(0, b.toJson().size());
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * The advice-file contract with the OSRS skill that writes advice.json (2026-10-17). Each case in
 * src/test/resources/contract/ is an advice file built by the skill's own code (its tests/contract.py exports them) plus
 * what this plugin must do with it: the offer-screen check, the "differs from the advice" warning, and which orders the
 * panel lists as still to place. The cases are the boundary bugs found in-game in October 2026.
 */
public class ContractTest
{
	private static final Gson GSON = new Gson();

	private static OfferTracker.Offer offer(JsonObject o)
	{
		final OfferTracker.Offer x = new OfferTracker.Offer(o.get("itemId").getAsInt(), o.get("item").getAsString(), o.get("state").getAsString(),
			o.get("price").getAsLong(), o.get("total").getAsInt(), o.has("done") ? o.get("done").getAsInt() : 0, 0);
		x.placedAt = o.has("placedAt") ? o.get("placedAt").getAsLong() : null;
		x.lastFillAt = o.has("lastFillAt") ? o.get("lastFillAt").getAsLong() : null;
		x.personal = o.has("personal") && o.get("personal").getAsBoolean();
		return x;
	}

	private static OfferTracker.Offer[] slots(JsonObject s)
	{
		final OfferTracker.Offer[] out = new OfferTracker.Offer[OfferTracker.SLOTS];
		if (s != null)
		{
			for (Map.Entry<String, JsonElement> e : s.entrySet())
			{
				out[Integer.parseInt(e.getKey())] = offer(e.getValue().getAsJsonObject());
			}
		}
		return out;
	}

	private static String str(JsonObject o, String k)
	{
		return o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsString() : null;
	}

	@Test
	public void everyContractCaseHolds() throws IOException
	{
		final Path dir = Paths.get("src", "test", "resources", "contract");
		final List<Path> files;
		try (Stream<Path> s = Files.list(dir))
		{
			files = s.filter(p -> p.toString().endsWith(".json")).sorted().collect(Collectors.toList());
		}
		assertFalse("no contract cases in " + dir, files.isEmpty());
		final List<String> failures = new ArrayList<>();
		for (Path f : files)
		{
			final JsonObject c = GSON.fromJson(new String(Files.readAllBytes(f), StandardCharsets.UTF_8), JsonObject.class);
			final String name = c.get("name").getAsString();
			if (!GSON.fromJson(c.get("advice"), Advice.class).usable())
			{
				failures.add(name + ": advice not usable");
				continue;
			}
			int i = 0;
			for (JsonElement el : c.getAsJsonArray("checks"))
			{
				final JsonObject k = el.getAsJsonObject();
				final String where = name + " check " + (i++) + " (" + k.get("type").getAsString() + ")";
				// a fresh Advice per check: markPlaced is state, and one check must not leak into the next
				final Advice a = GSON.fromJson(c.get("advice"), Advice.class);
				switch (k.get("type").getAsString())
				{
					case "check":
					{
						final Advice.Check r = a.check(k.get("itemId").getAsInt(), k.get("side").getAsString(), k.get("qty").getAsInt(),
							new OfferTracker.Offer[OfferTracker.SLOTS]);
						final String lines = String.join(" | ", r.lines);
						if (!r.level.equals(k.get("level").getAsString()))
						{
							failures.add(where + ": level " + r.level + ", expected " + k.get("level").getAsString() + " — " + lines);
						}
						final String want = str(k, "contains");
						if (want != null && !lines.contains(want))
						{
							failures.add(where + ": lines lack \"" + want + "\" — " + lines);
						}
						break;
					}
					case "mismatch":
					{
						final String got = a.placedMismatch(offer(k.getAsJsonObject("offer")));
						final String want = str(k, "expect");
						if (want == null ? got != null : got == null || !got.contains(want))
						{
							failures.add(where + ": got " + got + ", expected " + (want == null ? "no warning" : "\"" + want + "\""));
						}
						break;
					}
					case "toPlace":
					{
						if (k.has("markPlaced"))
						{
							for (JsonElement m : k.getAsJsonArray("markPlaced"))
							{
								a.markPlaced(offer(m.getAsJsonObject()));
							}
						}
						final List<String> got = a.toPlace(slots(k.getAsJsonObject("slots"))).stream()
							.map(o -> o.side + ":" + o.itemId + ":" + o.price).sorted().collect(Collectors.toList());
						final List<String> want = new ArrayList<>();
						for (JsonElement w : k.getAsJsonArray("expect"))
						{
							want.add(w.getAsString());
						}
						Collections.sort(want);
						if (!got.equals(want))
						{
							failures.add(where + ": to place " + got + ", expected " + want);
						}
						break;
					}
					case "reminders":
					{
						// each expected line is "SLOT KIND[ text the reminder contains]"; nothing else may fire
						final List<Reminders.Due> got = new Reminders().due(a, slots(k.getAsJsonObject("slots")), new Reminders.Settings(),
							k.get("now").getAsLong());
						final List<String> seen = got.stream().map(d -> d.slot + " " + d.kind + " — " + d.text).collect(Collectors.toList());
						final JsonArray want = k.getAsJsonArray("expect");
						if (got.size() != want.size())
						{
							failures.add(where + ": fired " + seen + ", expected " + want);
							break;
						}
						for (int j = 0; j < want.size(); j++)
						{
							final String[] w = want.get(j).getAsString().split(" ", 3);
							final Reminders.Due d = got.get(j);
							if (d.slot != Integer.parseInt(w[0]) || !d.kind.equals(w[1]) || (w.length > 2 && !d.text.contains(w[2])))
							{
								failures.add(where + ": fired " + seen + ", expected " + want);
								break;
							}
						}
						break;
					}
					default:
						failures.add(where + ": unknown check type");
				}
			}
		}
		assertTrue(String.join("\n", failures), failures.isEmpty());
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class DecantsTest
{
	private static Decants.Change c(String name, int delta)
	{
		return new Decants.Change(name.hashCode(), name, delta);
	}

	@Test
	public void bobsDecantIsFound()
	{
		// 324 (4)s into 1,296 (1)s, plus the empty vials bought for it
		List<Map<String, Object>> d = Decants.find(Arrays.asList(c("Super combat potion(4)", -324), c("Super combat potion(1)", 1296), c("Vial", -972)));
		assertEquals(1, d.size());
		assertEquals("Super combat potion", d.get(0).get("potion"));
		assertEquals(1296, d.get(0).get("doses"));
	}

	@Test
	public void combiningByHandIsADecantToo()
	{
		List<Map<String, Object>> d = Decants.find(Arrays.asList(c("Prayer potion(3)", -1), c("Prayer potion(1)", -1), c("Prayer potion(4)", 1), c("Vial", 1)));
		assertEquals(1, d.size());
		assertEquals(4, d.get(0).get("doses"));
	}

	@Test
	public void ordinaryInventoryChangesAreNot()
	{
		assertTrue(Decants.find(Arrays.asList(c("Super combat potion(4)", 10))).isEmpty());              // a withdrawal
		assertTrue(Decants.find(Arrays.asList(c("Super combat potion(4)", -1), c("Super combat potion(3)", 1))).isEmpty()); // a drink: a dose gone
		assertTrue(Decants.find(Arrays.asList(c("Prayer potion(4)", -2), c("Super restore(2)", 4))).isEmpty());  // different potions
		assertTrue(Decants.find(Arrays.asList(c("Coins", -5), c("Dragon chainbody", 1))).isEmpty());
	}

	@Test
	public void twoKindsAtOnceAreTwoDecants()
	{
		List<Map<String, Object>> d = Decants.find(Arrays.asList(c("Super combat potion(4)", -1), c("Super combat potion(2)", 2),
			c("Prayer potion(3)", -4), c("Prayer potion(4)", 3)));
		assertEquals(2, d.size());
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;
import org.junit.Test;

public class EventLogTest
{
	private static final long T0 = 1_790_000_000_000L;

	@Test
	public void archiveNamesSortByTime()
	{
		assertEquals("events-20260921T140000.jsonl", EventLog.archiveName(1789999200000L));
		assertTrue(EventLog.archiveName(T0).compareTo(EventLog.archiveName(T0 + 1000)) < 0);
		assertTrue(EventLog.isArchive(EventLog.archiveName(T0)));
		assertFalse(EventLog.isArchive("events.jsonl"));
		assertFalse(EventLog.isArchive("state.json"));
	}

	@Test
	public void onlyTheOldestArchivesBeyondTheLimitAreDeleted()
	{
		List<String> names = Arrays.asList("state.json", "events.jsonl", "events-20260101T000000.jsonl", "events-20260301T000000.jsonl",
			"events-20260201T000000.jsonl");
		assertEquals(Arrays.asList("events-20260101T000000.jsonl"), EventLog.toDelete(names, 2));
		assertTrue(EventLog.toDelete(names, 3).isEmpty());
	}

	@Test
	public void appendRotatesAtTheLimitAndKeepsTheNewestArchives() throws Exception
	{
		final Path tmp = Files.createTempDirectory("gebridge");
		final Filepath dir = Filepath.Unchecked.getRooted(tmp);
		final String line = "{\"t\":1}\n";                       // 8 bytes
		for (int i = 0; i < 40; i++)
		{
			EventLog.append(dir, line, 24, T0 + i * 1000L);        // a rotation every 3 lines
		}
		List<String> names;
		try (Stream<Path> s = Files.list(tmp))
		{
			names = s.map(p -> p.getFileName().toString()).sorted().collect(Collectors.toList());
		}
		long archives = names.stream().filter(EventLog::isArchive).count();
		assertEquals(EventLog.KEEP, archives);
		assertTrue(names.contains(EventLog.LIVE));
		assertTrue(Files.size(tmp.resolve(EventLog.LIVE)) <= 24);
		for (String n : names)
		{
			if (EventLog.isArchive(n))
			{
				assertEquals(24, Files.size(tmp.resolve(n)));       // every archive holds whole lines only
			}
		}
	}
}

