package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import org.junit.Test;

/**
 * Random order lifecycles in one slot, observed with gaps (missed updates, logouts, login bursts). Whatever the
 * client happens to show, the fills logged for an order must add up to the most it was seen filled, never go
 * negative, and every order seen must be placed (or baselined) exactly once.
 */
public class OfferTrackerPropertyTest
{
	@Test
	public void fillsAlwaysAddUpToWhatWasSeen()
	{
		for (long seed = 1; seed <= 500; seed++)
		{
			run(new Random(seed), seed);
		}
	}

	private static void run(Random rnd, long seed)
	{
		final OfferTracker t = new OfferTracker();
		long now = 1_790_000_000_000L;
		final Map<String, Integer> filled = new HashMap<>();   // order key → sum of logged fill qty
		final Map<String, Integer> maxSeen = new HashMap<>();  // order key → most seen filled
		final Map<String, Integer> openings = new HashMap<>(); // order key → placed/baseline count
		boolean first = true;
		for (int order = 0; order < 6; order++)
		{
			final boolean buy = rnd.nextBoolean();
			final int total = 1 + rnd.nextInt(500);
			final long price = 100 + order;                     // distinct per order, so each has its own key
			final String key = order + "";
			int done = 0;
			while (true)
			{
				done = Math.min(total, done + (rnd.nextInt(3) == 0 ? 0 : 1 + rnd.nextInt(Math.max(1, total / 3))));
				final String state = done == total ? (buy ? "BOUGHT" : "SOLD") : (buy ? "BUYING" : "SELLING");
				final boolean shown = rnd.nextInt(4) != 0;          // a quarter of updates are never seen
				if (rnd.nextInt(8) == 0)
				{
					t.markObserved(now);
					t.resetSession();                               // a logout
				}
				if (shown || done == total)
				{
					final boolean burst = rnd.nextInt(5) == 0;
					tally(t.observe(0, new OfferTracker.Offer(7, "x", state, price, total, done, done * price), now += 1000, burst),
						filled, openings, first);
					first = false;
					maxSeen.merge(key, done, Math::max);
				}
				if (done == total)
				{
					break;
				}
			}
			if (rnd.nextBoolean())
			{
				tally(t.observe(0, new OfferTracker.Offer(0, null, "EMPTY", 0, 0, 0, 0), now += 1000, false), filled, openings, false);
			}
		}
		for (Map.Entry<String, Integer> e : maxSeen.entrySet())
		{
			final int logged = filled.getOrDefault(e.getKey(), 0);
			final boolean baselined = e.getKey().equals("0");
			// a baseline books nothing, so the first order's fills start from its first sighting
			assertTrue("seed " + seed + ": order " + e.getKey() + " logged " + logged + " > seen " + e.getValue(), logged <= e.getValue());
			if (!baselined)
			{
				assertEquals("seed " + seed + ": order " + e.getKey(), (int) e.getValue(), logged);
			}
			assertEquals("seed " + seed + ": order " + e.getKey() + " opened", 1, (int) openings.getOrDefault(e.getKey(), 0));
		}
	}

	private static void tally(List<Map<String, Object>> evs, Map<String, Integer> filled, Map<String, Integer> openings, boolean first)
	{
		for (Map<String, Object> e : evs)
		{
			final String key = (((Long) e.get("price")) - 100) + "";
			final String type = (String) e.get("type");
			if ("fill".equals(type))
			{
				assertTrue("fill qty must be positive", (Integer) e.get("qty") > 0);
				filled.merge(key, (Integer) e.get("qty"), Integer::sum);
			}
			else if ("placed".equals(type) || "baseline".equals(type))
			{
				openings.merge(key, 1, Integer::sum);
			}
			else if ("anomaly".equals(type))
			{
				throw new AssertionError("anomaly on a monotonic sequence: " + e);
			}
		}
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Test;

public class OfferTrackerTest
{
	private static final long T0 = 1_790_000_000_000L;

	private static OfferTracker.Offer buy(int done, long spent)
	{
		return new OfferTracker.Offer(3140, "Dragon chainbody", done == 24 ? "BOUGHT" : "BUYING", 189_334, 24, done, spent);
	}

	private static OfferTracker.Offer empty()
	{
		return new OfferTracker.Offer(0, null, "EMPTY", 0, 0, 0, 0);
	}

	private static List<String> types(List<Map<String, Object>> evs)
	{
		return evs.stream().map(e -> (String) e.get("type")).collect(Collectors.toList());
	}

	private static OfferTracker remembering(OfferTracker.Offer o, long observedAt)
	{
		OfferTracker t = new OfferTracker();
		o.observedAt = observedAt;
		t.restore(0, o);
		return t;
	}

	@Test
	public void firstRunRecordsABaselineAndBooksNothing()
	{
		OfferTracker t = new OfferTracker();
		List<Map<String, Object>> evs = t.observe(0, buy(10, 1_893_340), T0);
		assertEquals(List.of("baseline"), types(evs));
		assertTrue(t.observe(1, empty(), T0).isEmpty());
	}

	@Test
	public void liveFillIsTimedAndNotOffline()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 60_000);
		assertTrue(t.observe(0, buy(10, 1_893_340), T0).isEmpty());
		List<Map<String, Object>> evs = t.observe(0, buy(15, 2_840_010), T0 + 5_000);
		assertEquals(List.of("fill"), types(evs));
		assertEquals(5, evs.get(0).get("qty"));
		assertEquals(946_670L, evs.get(0).get("gp"));
		assertNull(evs.get(0).get("offline"));
		assertEquals(T0 + 5_000, (long) t.get(0).lastFillAt);
	}

	@Test
	public void changeFirstSeenAtLoginIsOfflineWithItsWindow()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 3_600_000);
		List<Map<String, Object>> evs = t.observe(0, buy(24, 4_544_016), T0);
		assertEquals(List.of("fill", "completed"), types(evs));
		assertEquals(14, evs.get(0).get("qty"));
		assertEquals(true, evs.get(0).get("offline"));
		assertEquals(OfferTracker.iso(T0 - 3_600_000), evs.get(0).get("since"));
		assertEquals(true, evs.get(1).get("offline"));
	}

	@Test
	public void fullLifecycleInOneSession()
	{
		OfferTracker t = remembering(empty(), T0 - 1_000);
		assertTrue(t.observe(0, empty(), T0).isEmpty());
		assertEquals(List.of("placed"), types(t.observe(0, buy(0, 0), T0 + 1)));
		assertEquals(T0 + 1, (long) t.get(0).placedAt);
		assertEquals(List.of("fill"), types(t.observe(0, buy(20, 3_786_680), T0 + 2)));
		assertEquals(List.of("fill", "completed"), types(t.observe(0, buy(24, 4_544_016), T0 + 3)));
		List<Map<String, Object>> evs = t.observe(0, empty(), T0 + 4);
		assertEquals(List.of("cleared"), types(evs));
		assertNull(evs.get(0).get("unobserved"));
	}

	@Test
	public void instantFillOnPlacementBooksTheUnits()
	{
		OfferTracker t = remembering(empty(), T0 - 1_000);
		t.observe(0, empty(), T0);
		List<Map<String, Object>> evs = t.observe(0, buy(5, 946_670), T0 + 1);
		assertEquals(List.of("placed", "fill"), types(evs));
		assertEquals(5, evs.get(1).get("qty"));
	}

	@Test
	public void cancelThenCollect()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 1_000);
		t.observe(0, buy(10, 1_893_340), T0);
		OfferTracker.Offer c = buy(10, 1_893_340);
		c.state = "CANCELLED_BUY";
		assertEquals(List.of("cancelled"), types(t.observe(0, c, T0 + 1)));
		List<Map<String, Object>> evs = t.observe(0, empty(), T0 + 2);
		assertEquals(List.of("cleared"), types(evs));
		assertNull(evs.get(0).get("unobserved"));
	}

	@Test
	public void slotEmptiedWhileAwayIsFlaggedUnobserved()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 3_600_000);
		List<Map<String, Object>> evs = t.observe(0, empty(), T0);
		assertEquals(List.of("cleared"), types(evs));
		assertEquals(true, evs.get(0).get("unobserved"));
		assertEquals(true, evs.get(0).get("offline"));
	}

	@Test
	public void orderReplacedWhileAwayClearsTheOldAndPlacesTheNew()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 3_600_000);
		OfferTracker.Offer sell = new OfferTracker.Offer(3140, "Dragon chainbody", "SELLING", 197_452, 24, 3, 580_000);
		List<Map<String, Object>> evs = t.observe(0, sell, T0);
		assertEquals(List.of("cleared", "placed", "fill"), types(evs));
		assertEquals(true, evs.get(0).get("unobserved"));
		assertEquals("sell", evs.get(2).get("side"));
		assertEquals(true, t.get(0).placedOffline);
	}

	@Test
	public void logoutMakesTheNextSightOfflineAgain()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 1_000);
		t.observe(0, buy(10, 1_893_340), T0);
		t.markObserved(T0 + 10_000);
		t.resetSession();
		List<Map<String, Object>> evs = t.observe(0, buy(12, 2_271_888), T0 + 20_000);
		assertEquals(true, evs.get(0).get("offline"));
		assertEquals(OfferTracker.iso(T0 + 10_000), evs.get(0).get("since"));
	}

	@Test
	public void stateJsonKeepsTheOldExporterFieldNames()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0);
		@SuppressWarnings("unchecked")
		Map<String, Object> slot = (Map<String, Object>) ((Map<String, Object>) t.toJson().get("offers")).get("0");
		assertEquals("BUYING", slot.get("state"));
		assertEquals(189_334L, slot.get("listedPrice"));
		assertEquals(14, slot.get("remainingQuantity"));
		assertEquals("Dragon chainbody", slot.get("itemName"));
	}
	@Test
	public void fillArrivingInTheLoginBurstAfterTheSlotWasSeenIsOffline()
	{
		// the slot comes back unchanged at login, then fills made while logged out arrive a second later
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 1_000);
		t.observe(0, buy(10, 1_893_340), T0);
		t.markObserved(T0 + 10_000);
		t.resetSession();
		assertTrue(t.observe(0, buy(10, 1_893_340), T0 + 60_000, true).isEmpty());
		List<Map<String, Object>> evs = t.observe(0, buy(14, 2_650_676), T0 + 61_000, true);
		assertEquals(true, evs.get(0).get("offline"));
		assertEquals(OfferTracker.iso(T0 + 10_000), evs.get(0).get("since"));
		// after the burst, a change is live again
		assertNull(t.observe(0, buy(15, 2_840_010), T0 + 120_000, false).get(0).get("offline"));
	}
	@Test
	public void collectionsAccumulatePerOrderAndResetWithANewOrder()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 1_000);
		t.observe(0, buy(10, 1_893_340), T0);
		Map<String, Object> e = t.collect(0, 6, 0, java.util.Collections.emptyList(), T0 + 1);
		assertEquals("collected", e.get("type"));
		assertEquals(6, e.get("collectedQty"));
		t.observe(0, buy(15, 2_840_010), T0 + 2);                  // later fills keep the running total
		assertEquals(6, t.get(0).collectedQty);
		assertEquals(10, ((Map<String, Object>) t.collect(0, 4, 0, java.util.Collections.emptyList(), T0 + 3)).get("collectedQty"));
		@SuppressWarnings("unchecked")
		Map<String, Object> slot = (Map<String, Object>) ((Map<String, Object>) t.toJson().get("offers")).get("0");
		assertEquals(10, slot.get("collectedQuantity"));
		t.observe(0, empty(), T0 + 4);
		t.observe(0, new OfferTracker.Offer(3140, "Dragon chainbody", "SELLING", 197_452, 15, 0, 0), T0 + 5);
		assertEquals(0, t.get(0).collectedQty);                    // a new order starts from nothing
		assertNull(t.collect(1, 3, 0, java.util.Collections.emptyList(), T0 + 6));   // nothing in that slot to own it
	}
	@Test
	public void aLiveSellIsNotCreditedWithItsOwnItemComingOutOfTheBox()
	{
		// a cancelled ask returned its 154 scrolls; the emptied box reached the client after the item was re-listed
		OfferTracker.Offer relisted = new OfferTracker.Offer(12786, "Magic shortbow scroll", "SELLING", 51_443, 154, 1, 51_443);
		assertEquals(0, OfferTracker.ownItemCollected(relisted, 154));
		relisted.state = "CANCELLED_SELL";
		assertEquals(154, OfferTracker.ownItemCollected(relisted, 154));
		assertEquals(6, OfferTracker.ownItemCollected(buy(10, 1_893_340), 6));
	}

	@Test
	public void personalTagFollowsTheOrderUntilItLeaves()
	{
		OfferTracker t = remembering(buy(10, 1_893_340), T0 - 1_000);
		t.observe(0, buy(10, 1_893_340), T0);
		Map<String, Object> e = t.tag(0, true, T0 + 1);
		assertEquals("tag", e.get("type"));
		assertEquals(true, e.get("personal"));
		assertEquals(189_334L, e.get("price"));
		t.observe(0, buy(12, 2_272_008), T0 + 2);
		assertTrue(t.get(0).personal);
		assertEquals(true, ((Map<?, ?>) ((Map<?, ?>) t.toJson().get("offers")).get("0")).get("personal"));
		t.observe(0, empty(), T0 + 3);
		t.observe(0, buy(0, 0), T0 + 4);
		assertTrue(!t.get(0).personal);
		assertNull(t.tag(1, true, T0 + 5));
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

public class RemindersTest
{
	private static final long H = 3_600_000L;
	private static final long NOW = 1_800_000_000_000L;
	private static final Gson GSON = new Gson();

	/** Synthetic advice: slot 0 an ask with its grace trim, slot 1 an ask in a held dip, slot 2 a bid, and a pick. */
	private static Advice advice(long generatedAt)
	{
		return GSON.fromJson("{\"schema\":1,\"generatedAt\":" + generatedAt + ","
			+ "\"deadlines\":{\"askGraceHours\":5,\"bidStallHours\":6,\"bidDeadHours\":12},"
			+ "\"slots\":[{\"slot\":0,\"itemId\":9001,\"item\":\"Alpha rune\",\"side\":\"sell\",\"price\":1000,\"total\":100,\"action\":\"keep\",\"trimTo\":950},"
			+ "{\"slot\":1,\"itemId\":9002,\"item\":\"Beta bar\",\"side\":\"sell\",\"price\":2000,\"total\":50,\"action\":\"keep\",\"holdUntil\":" + (NOW - H) + ",\"holdTrimTo\":1800},"
			+ "{\"slot\":2,\"itemId\":9003,\"item\":\"Gamma seed\",\"side\":\"buy\",\"price\":300,\"total\":400,\"action\":\"keep\",\"listAt\":330}],"
			+ "\"orders\":[{\"itemId\":9004,\"item\":\"Delta hide\",\"side\":\"buy\",\"price\":700,\"qty\":80,\"why\":\"pick\",\"listLater\":760}]}",
			Advice.class);
	}

	private static OfferTracker.Offer offer(int id, String item, String state, long price, int total, int done, long placedAgo, Long fillAgo)
	{
		final OfferTracker.Offer o = new OfferTracker.Offer(id, item, state, price, total, done, 0);
		o.placedAt = NOW - placedAgo;
		o.lastFillAt = fillAgo == null ? null : NOW - fillAgo;
		return o;
	}

	private static List<String> texts(List<Reminders.Due> d)
	{
		return d.stream().map(x -> x.slot + " " + x.kind + ": " + x.text).collect(Collectors.toList());
	}

	@Test
	public void eachDeadlineFiresOnceWithTheAdvicesPrice()
	{
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 6 * H, null);       // past its 5 h grace
		o[1] = offer(9002, "Beta bar", "SELLING", 2000, 50, 0, 30 * H, null);         // dip hold ended an hour ago
		o[2] = offer(9003, "Gamma seed", "BOUGHT", 300, 400, 400, 2 * H, 20 * 60_000L); // completed 20 min ago
		o[3] = offer(9004, "Delta hide", "BUYING", 700, 80, 0, 13 * H, null);         // the pick, quiet 13 h
		final Reminders r = new Reminders();
		final List<String> t = texts(r.due(advice(NOW - H), o, new Reminders.Settings(), NOW));
		assertEquals(4, t.size());
		assertEquals("0 grace: Alpha rune: unsold 5 h after listing — trim to 950", t.get(0));
		assertEquals("1 dip: Beta bar: the dip hold is over — trim toward 1,800", t.get(1));
		assertEquals("2 collect: Gamma seed: bought 400 — collect and list at 330", t.get(2));
		assertEquals("3 dead: Delta hide: no fills in 12 h — the advice cancels bids this quiet", t.get(3));
		assertTrue(r.due(advice(NOW - H), o, new Reminders.Settings(), NOW + 60_000L).isEmpty());     // once only
	}

	@Test
	public void beforeTheirDeadlinesNothingFires()
	{
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 4 * H, null);
		o[0 + 1] = offer(9002, "Beta bar", "SELLING", 2000, 50, 0, 30 * H, null);
		o[2] = offer(9003, "Gamma seed", "BOUGHT", 300, 400, 400, 2 * H, 5 * 60_000L);
		o[3] = offer(9004, "Delta hide", "BUYING", 700, 80, 10, 13 * H, 3 * H);      // a fill 3 h ago: not stalled
		final Advice a = advice(NOW - H);
		a.slots().get(1).holdUntil = NOW + H;                                          // dip still held: no grace either
		assertTrue(texts(new Reminders().due(a, o, new Reminders.Settings(), NOW)).isEmpty());
	}

	@Test
	public void aPartFilledBidStallsAndAnAskStillFillingWaits()
	{
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[3] = offer(9004, "Delta hide", "BUYING", 700, 80, 10, 13 * H, 7 * H);
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 30, 6 * H, H);          // sold some an hour ago
		final List<String> t = texts(new Reminders().due(advice(NOW - H), o, new Reminders.Settings(), NOW));
		assertEquals(List.of("3 stall: Delta hide: no fills in 6 h — a check-in would re-place or cancel it"), t);
	}

	@Test
	public void personalAndUnadvisedOrdersAreNotTimed()
	{
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 6 * H, null);
		o[0].personal = true;
		o[4] = offer(9100, "Other thing", "BUYING", 5, 1000, 0, 20 * H, null);
		o[5] = offer(9001, "Alpha rune", "SELLING", 990, 100, 0, 6 * H, null);           // not the advised price
		assertTrue(new Reminders().due(advice(NOW - H), o, new Reminders.Settings(), NOW).isEmpty());
	}

	@Test
	public void oldAdviceSaysSoAndSwitchesTurnTriggersOff()
	{
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 6 * H, null);
		o[2] = offer(9003, "Gamma seed", "BOUGHT", 300, 400, 400, 2 * H, 20 * 60_000L);
		final Reminders.Settings s = new Reminders.Settings();
		s.collect = false;
		final List<String> t = texts(new Reminders().due(advice(NOW - 5 * H), o, s, NOW));
		assertEquals(List.of("0 grace: Alpha rune: unsold 5 h after listing — trim to 950 (advice 5h old)"), t);
	}

	@Test
	public void withoutDeadlinesOnlyTheCollectNudgeRuns()
	{
		final Advice a = advice(NOW - H);
		a.deadlines = null;                    // advice from a tool that predates 0.7.0
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 6 * H, null);
		o[2] = offer(9003, "Gamma seed", "BOUGHT", 300, 400, 400, 2 * H, 20 * 60_000L);
		assertEquals(List.of("2 collect: Gamma seed: bought 400 — collect and list at 330"), texts(new Reminders().due(a, o, new Reminders.Settings(), NOW)));
	}

	@Test
	public void clocksCountDownThenTurnDue()
	{
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 3 * H, null);         // 2 h of its 5 h grace left
		o[3] = offer(9004, "Delta hide", "BUYING", 700, 80, 0, 13 * H, null);            // the pick, 13 h without a fill
		final java.util.Map<Integer, Reminders.Clock> c = Reminders.clocks(advice(NOW - H), o, new Reminders.Settings(), NOW);
		assertEquals(false, c.get(0).due);
		assertEquals("trim 950", c.get(0).action);
		assertEquals("2h0m", Reminders.left(c.get(0).at - NOW));
		assertEquals("dead", c.get(3).kind);
		assertEquals(true, c.get(3).due);
		final Reminders.Settings noDead = new Reminders.Settings();
		noDead.dead = false;
		assertEquals("stall", Reminders.clocks(advice(NOW - H), o, noDead, NOW).get(3).kind);
		assertEquals("<1m", Reminders.left(30_000));
		assertEquals("45m", Reminders.left(45 * 60_000L));
	}

	@Test
	public void aStalledBidNamesWhatTheAdviceSaidItBrings()
	{
		// 0.7.3 (expeditious bracelet 2026-10-27): "now: re-place" without a price
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[2] = offer(9003, "Gamma seed", "BUYING", 300, 400, 0, 7 * H, null);              // 7 h without a fill
		final Advice a = advice(NOW - H);
		assertEquals("re-place (check in)", Reminders.clocks(a, o, new Reminders.Settings(), NOW).get(2).action);
		a.slots().get(2).replaceTo = 310L;
		assertEquals("re-place 310", Reminders.clocks(a, o, new Reminders.Settings(), NOW).get(2).action);
		assertEquals(List.of("2 stall: Gamma seed: no fills in 6 h — re-place at 310"),
			texts(new Reminders().due(a, o, new Reminders.Settings(), NOW)));
		final Advice old = advice(NOW - 5 * H);
		old.slots().get(2).replaceTo = 310L;
		assertEquals(List.of("2 stall: Gamma seed: no fills in 6 h — re-place at 310 (advice 5h old)"),
			texts(new Reminders().due(old, o, new Reminders.Settings(), NOW)));
		a.slots().get(2).stallCancel = true;                                                 // a cancel day of the re-place A/B
		assertEquals("cancel", Reminders.clocks(a, o, new Reminders.Settings(), NOW).get(2).action);
		assertEquals(List.of("2 stall: Gamma seed: no fills in 6 h — the advice cancels it"),
			texts(new Reminders().due(a, o, new Reminders.Settings(), NOW)));
	}

	@Test
	public void thePanelShowsKeptOrdersDeadlines()
	{
		final Advice a = advice(NOW - H);
		a.slots().get(0).action = "keep";
		final OfferTracker.Offer[] o = new OfferTracker.Offer[8];
		o[0] = offer(9001, "Alpha rune", "SELLING", 1000, 100, 0, 3 * H, null);
		o[3] = offer(9004, "Delta hide", "BUYING", 700, 80, 0, 13 * H, null);
		final AdviceView v = AdviceView.build(a, o, java.util.Collections.emptyMap(), null, NOW, 12 * H, true,
			Reminders.clocks(a, o, new Reminders.Settings(), NOW));
		final java.util.List<String> lines = v.lines.stream().map(l -> l.left + " | " + l.right).collect(Collectors.toList());
		assertTrue(lines.toString(), lines.contains("0 Alpha rune | trim 950 in 2h0m"));
		assertTrue(lines.toString(), lines.contains("3 Delta hide | now: cancel"));
		assertEquals(AdviceView.ACT, v.slots.get(3));
		assertTrue(!v.slots.containsKey(0));                                               // not due yet: no outline
		final AdviceView without = AdviceView.build(a, o, java.util.Collections.emptyMap(), null, NOW, 12 * H, true);
		assertTrue(without.lines.stream().noneMatch(l -> l.left.startsWith("0 ")));        // without clocks: counted as kept
	}
}

package io.github.y5c.gebridge;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class StoresTest
{
	@Test
	public void pouchSlotsInOrderEmptyAndUnknownSkipped()
	{
		final Map<Integer, Integer> vb = new HashMap<>();
		vb.put(VarbitID.RUNE_POUCH_TYPE_1, 6);    // a rune type the enum maps
		vb.put(VarbitID.RUNE_POUCH_QUANTITY_1, 16000);
		vb.put(VarbitID.RUNE_POUCH_TYPE_2, 9);
		vb.put(VarbitID.RUNE_POUCH_QUANTITY_2, 0);   // type set, quantity 0: empty
		vb.put(VarbitID.RUNE_POUCH_TYPE_4, 99);      // a type the enum does not map: skipped
		vb.put(VarbitID.RUNE_POUCH_QUANTITY_4, 5);
		vb.put(VarbitID.RUNE_POUCH_TYPE_6, 7);       // the sixth slot (divine rune pouch) is read too
		vb.put(VarbitID.RUNE_POUCH_QUANTITY_6, 250);
		final JsonObject p = Stores.runePouch(v -> vb.getOrDefault(v, 0),
			t -> t == 6 ? 560 : t == 7 ? 565 : -1,
			id -> id == 560 ? "Death rune" : "Blood rune",
			id -> id == 560 ? 200L : 350L);
		assertTrue(p.get("loaded").getAsBoolean());
		assertEquals(2, p.get("itemCount").getAsInt());
		final JsonObject items = p.getAsJsonObject("items");
		assertEquals("Death rune", items.getAsJsonObject("0").get("name").getAsString());
		assertEquals(16000, items.getAsJsonObject("0").get("quantity").getAsInt());
		assertEquals(565, items.getAsJsonObject("5").get("id").getAsInt());
		assertEquals(16000L * 200 + 250L * 350, p.get("value").getAsLong());
		assertFalse(items.has("1"));
		assertFalse(items.has("3"));
	}

	@Test
	public void anEmptyPouchIsLoadedAndEmpty()
	{
		final JsonObject p = Stores.runePouch(v -> 0, t -> 560, id -> "x", id -> 1L);
		assertTrue(p.get("loaded").getAsBoolean());
		assertEquals(0, p.get("itemCount").getAsInt());
	}

	@Test
	public void pouchVarbitsAreRecognised()
	{
		assertTrue(Stores.isPouchVarbit(VarbitID.RUNE_POUCH_TYPE_1));
		assertTrue(Stores.isPouchVarbit(VarbitID.RUNE_POUCH_QUANTITY_6));
		assertFalse(Stores.isPouchVarbit(VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE));
	}
}

